    _cap = io.StringIO()
    with contextlib.redirect_stdout(_cap):
        _rc = match_deferrals.main(["--pr", "700", "--diff", str(_diff_f),
                                    "--findings", str(_find_f)])
    _res = json.loads(_cap.getvalue())
    assert_eq("#621 main: helper ran (exit 0)", 0, _rc)
