# main() effort-report wiring (issue #554, pr-test-analyzer #1/#2): a config that
# produces a VALID per-agent effort override must route its fallback report to
# STDERR while stdout stays pure JSON (the load-bearing engine contract — the
# review engine json-parses stdout). The existing main() tests run against a
# nonexistent config (no overrides → no report), so this is the only coverage
# that a regression writing the report to stdout would corrupt the engine parse.
with _tempfile.NamedTemporaryFile('w', suffix='.json', delete=False) as _e554f:
    _e554f.write('{"prflow_review":{"agent_overrides":'
                 '{"devflow:code-reviewer":{"effort":"low"}}}}')
    _e554_cfg = _e554f.name
try:
    _o554, _e554 = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(_o554), contextlib.redirect_stderr(_e554):
        _rc554 = _rro.main(["devflow:code-reviewer", "--config", _e554_cfg])
    assert_eq("main(#554): valid effort override exits 0", 0, _rc554)
    # stdout is pure JSON — no ::notice::/::warning:: leaked onto it.
    assert_eq("main(#554): stdout stays pure JSON (report never on stdout)",
              {"devflow:code-reviewer": {"effort": "low"}},
              json.loads(_o554.getvalue()))
    assert_eq("main(#554): the ::notice:: fallback report is on stderr",
              True, "::notice::" in _e554.getvalue()
              and "per-agent effort was NOT applied" in _e554.getvalue())
    # --effort-supported false wiring: the SAME override now reports a
    # capability-restricted ::warning:: naming the provider (the CLI flag is
    # threaded to decide/format, not just the pure functions).
    _o554b, _e554b = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(_o554b), contextlib.redirect_stderr(_e554b):
        _rc554b = _rro.main(["devflow:code-reviewer", "--config", _e554_cfg,
                             "--effort-supported", "false"])
    assert_eq("main(#554): --effort-supported false exits 0", 0, _rc554b)
    assert_eq("main(#554): --effort-supported false → capability ::warning:: on stderr",
              True, "::warning::" in _e554b.getvalue()
              and "effort_supported" in _e554b.getvalue())
    assert_eq("main(#554): stdout still pure JSON under --effort-supported false",
              {"devflow:code-reviewer": {"effort": "low"}},
              json.loads(_o554b.getvalue()))
finally:
    _os.unlink(_e554_cfg)

# --effort-supported ENV fallback (issue #1772): with the CLI flag omitted the
# resolver reads PRFLOW_EFFORT_SUPPORTED; absent/unrecognized falls back to "true"
# (the Anthropic path) and an explicit CLI flag still wins.
with _tempfile.NamedTemporaryFile('w', suffix='.json', delete=False) as _e1772f:
    _e1772f.write('{"prflow_review":{"agent_overrides":'
                  '{"devflow:code-reviewer":{"effort":"low"}}}}')
    _e1772_cfg = _e1772f.name
_prev_env_1772 = _os.environ.get("PRFLOW_EFFORT_SUPPORTED")


def _run_1772(argv, env_val):
    if env_val is None:
        _os.environ.pop("PRFLOW_EFFORT_SUPPORTED", None)
    else:
        _os.environ["PRFLOW_EFFORT_SUPPORTED"] = env_val
    _o, _e = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(_o), contextlib.redirect_stderr(_e):
        _rc = _rro.main(argv)
    return _rc, _o.getvalue(), _e.getvalue()


try:
    _base_argv_1772 = ["devflow:code-reviewer", "--config", _e1772_cfg]
    # env false, no CLI flag → capability ::warning:: naming the provider (#1772 wiring).
    _rc_f, _o_f, _e_f = _run_1772(_base_argv_1772, "false")
    assert_eq("main(#1772): PRFLOW_EFFORT_SUPPORTED=false exits 0", 0, _rc_f)
    assert_eq("main(#1772): env false → provider ::warning:: with no CLI flag",
              True, "::warning::" in _e_f and "effort_supported" in _e_f)
    assert_eq("main(#1772): env false keeps stdout pure JSON",
              {"devflow:code-reviewer": {"effort": "low"}}, json.loads(_o_f))
    # env true → benign ::notice::, no provider warning.
    _rc_t, _o_t, _e_t = _run_1772(_base_argv_1772, "true")
    assert_eq("main(#1772): env true → benign ::notice::, no provider ::warning::",
              True, "::notice::" in _e_t and "::warning::" not in _e_t)
    # env absent → defaults to true (benign notice), preserving today's behavior.
    _rc_a, _o_a, _e_a = _run_1772(_base_argv_1772, None)
    assert_eq("main(#1772): env absent defaults to effort supported (benign notice)",
              True, "::notice::" in _e_a and "::warning::" not in _e_a)
    # explicit --effort-supported true WINS over env false (flag precedence).
    _rc_o, _o_o, _e_o = _run_1772(
        _base_argv_1772 + ["--effort-supported", "true"], "false")
    assert_eq("main(#1772): explicit --effort-supported true overrides env false",
              True, "::notice::" in _e_o and "::warning::" not in _e_o)
    # symmetric precedence: explicit --effort-supported false WINS over env true →
    # provider ::warning::, pinning that the CLI flag governs in both directions.
    _rc_ff, _o_ff, _e_ff = _run_1772(
        _base_argv_1772 + ["--effort-supported", "false"], "true")
    assert_eq("main(#1772): explicit --effort-supported false overrides env true",
              True, "::warning::" in _e_ff and "effort_supported" in _e_ff)
    # unrecognized env value → true + a warning naming the var, never silent coercion.
    # The provider-capability ::warning:: (carrying lowercase 'effort_supported') must be
    # ABSENT, or "fell back to true" is only implied by the notice.
    _rc_u, _o_u, _e_u = _run_1772(_base_argv_1772, "yes")
    assert_eq("main(#1772): unrecognized env value falls back to true with a warning",
              True, "::notice::" in _e_u and "PRFLOW_EFFORT_SUPPORTED" in _e_u
              and "effort_supported" not in _e_u)
    # a present-but-empty env value is a defensive input (the provider step normally exports
    # 'true'/'false', but a skipped/output-less provider step would export empty): treated as
    # absent → benign ::notice::, no warning, NOT the unrecognized-value branch.
    _rc_e, _o_e, _e_e = _run_1772(_base_argv_1772, "")
    assert_eq("main(#1772): empty env value → benign ::notice::, no warning",
              True, "::notice::" in _e_e and "::warning::" not in _e_e)
    _rc_ws, _o_ws, _e_ws = _run_1772(_base_argv_1772, "   ")
    assert_eq("main(#1772): whitespace-only env value → benign ::notice::, no warning",
              True, "::notice::" in _e_ws and "::warning::" not in _e_ws)
    # case/whitespace normalization (strip().lower()): ' False ' → false → provider
    # ::warning:: — a regression dropping .strip()/.lower() would silently fail this open.
    _rc_c, _o_c, _e_c = _run_1772(_base_argv_1772, " False ")
    assert_eq("main(#1772): ' False ' normalizes to false → provider ::warning::",
              True, "::warning::" in _e_c and "effort_supported" in _e_c)
    _rc_ct, _o_ct, _e_ct = _run_1772(_base_argv_1772, " TRUE ")
    assert_eq("main(#1772): ' TRUE ' normalizes to true → benign ::notice::",
              True, "::notice::" in _e_ct and "::warning::" not in _e_ct)
    # The --effort-json observability branch consumes the SAME resolved local; a regression
    # re-deriving it from args.effort_supported (now None by default) would read false on
    # every env-absent run, so pin both directions through that branch.
    _json_argv_1772 = _base_argv_1772 + ["--effort-json"]
    _rc_jf, _o_jf, _e_jf = _run_1772(_json_argv_1772, "false")
    assert_eq("main(#1772): --effort-json exits 0 with env false", 0, _rc_jf)
    assert_eq("main(#1772): --effort-json env false → provider capability fallback_reason",
              True, "effort_supported is false"
              in json.loads(_o_jf)["devflow:code-reviewer"]["fallback_reason"])
    _rc_ja, _o_ja, _e_ja = _run_1772(_json_argv_1772, None)
    assert_eq("main(#1772): --effort-json env absent → no-seam reason, not the provider one",
              True, "effort_supported is false"
              not in json.loads(_o_ja)["devflow:code-reviewer"]["fallback_reason"])
finally:
    if _prev_env_1772 is None:
        _os.environ.pop("PRFLOW_EFFORT_SUPPORTED", None)
    else:
        _os.environ["PRFLOW_EFFORT_SUPPORTED"] = _prev_env_1772
    _os.unlink(_e1772_cfg)

# A non-object `default` on the real read_raw path: the warning must name the real
# consequence (no fallback for no-entry agents), NOT the nonsensical "default still
# applies" phrasing meaningful only for a real agent key.
with _tempfile.NamedTemporaryFile('w', suffix='.json', delete=False) as _ndf:
    _ndf.write('{"prflow_review":{"agent_overrides":{"default":"high"}}}')
    _nd_cfg = _ndf.name
try:
    _ndraw, _ndwarn = _rro.read_raw(
        ["devflow:code-reviewer"], _config_get_sh, _nd_cfg)
    assert_eq("read_raw: non-object default is not added to raw",
              False, "default" in _ndraw)
    _dmsg = [w for w in _ndwarn if "[default]" in w and "is not an object" in w]
    assert_eq("read_raw: non-object default surfaces a warning", 1, len(_dmsg))
    assert_eq("read_raw: non-object default warning avoids 'default still applies'",
              False, any("default still applies" in w for w in _dmsg))
    assert_eq("read_raw: non-object default warning names the real consequence",
              True, any("no fallback default" in w for w in _dmsg))
finally:
    _os.unlink(_nd_cfg)

# Drift guard: the resolver's roster must stay byte-identical to the schema's
# agent_overrides property keys (minus `default`). A tenth subagent added to the
# schema but not here (or vice versa) breaks config/dispatch/telemetry alignment.
#
# Compared over EVERY accepted namespace, not just the canonical one. The schema
# enumerates a key per accepted namespace under `additionalProperties: false`, so
# a consumer's already-committed alias-namespaced override keeps validating across
# a plugin rename — the frozen-key guarantee. The expectation is DERIVED from the
# declared namespaces (never a hand-listed alias set), so it stays a drift signal
# rather than an alias-list assumption: the property actually under guard is the
# LEAF set, and a leaf added on one side and not the other still breaks this on
# any alias configuration.
_schema_path = SCRIPTS.parent / '.prflow' / 'config.schema.json'
with open(_schema_path) as _sf:
    _schema = json.load(_sf)
_schema_keys = set(
    _schema["properties"]["prflow_review"]["properties"]["agent_overrides"]["properties"]
)
with open(SCRIPTS.parent / '.claude-plugin' / 'plugin.json') as _pjf:
    _CANON_NS = json.load(_pjf)["name"] + ":"
assert_eq("schema agent_overrides keys == every accepted namespace x the leaves + 'default'",
          {_ns + _leaf for _ns in _rro.AGENT_NAMESPACES for _leaf in _rro.AGENT_LEAVES}
          | {"default"}, _schema_keys)
# …and the canonical namespace really is one the resolver accepts, so the guard
# above is comparing against a live roster rather than a string it made up.
assert_eq("resolve: the canonical namespace is an accepted agent namespace",
          True, _CANON_NS in _rro.AGENT_NAMESPACES)

# T4 (issue #425): every agent_overrides entry (all nine agents + `default`) declares
# the optional `iterations` property as a string enum whose ONLY value is "first-only",
# and each entry stays additionalProperties:false (so a stale/typo'd entry key — and an
# out-of-enum iterations value in a validated config — is rejected outright). This pins
# the schema surface the resolver's VALID_ITERATIONS mirrors.
_ao_entries = (
    _schema["properties"]["prflow_review"]["properties"]["agent_overrides"]["properties"]
)
for _ent_name, _ent in _ao_entries.items():
    _it = _ent.get("properties", {}).get("iterations")
    assert_eq(f"#425 schema: agent_overrides[{_ent_name}] declares iterations enum ['first-only']",
              {"type": "string", "enum": ["first-only"]}, _it)
    assert_eq(f"#425 schema: agent_overrides[{_ent_name}] stays additionalProperties:false",
              False, _ent.get("additionalProperties"))
assert_eq("#425 schema: VALID_ITERATIONS mirrors the schema enum",
          ("first-only",), _rro.VALID_ITERATIONS)

# issue #1646: every agent_overrides entry declares the optional `model` property as a
# string enum whose members are exactly the Agent tool's accepted aliases
# (sonnet/opus/haiku/fable), and each entry stays additionalProperties:false — so a
# config setting `model` to a full identifier is rejected for every entry property the
# schema declares. This pins the schema surface the resolver's VALID_MODELS mirrors.
# RED before #1646: `model` was {"type": "string"} with no enum, so `claude-opus-4-8`
# validated cleanly.
# Cardinality guard: an empty _ao_entries would make the per-entry loop below assert
# nothing (vacuous pass). The schema declares default + nine leaves x two namespaces.
assert_eq("#1646 schema: agent_overrides declares a non-trivial entry set (loop not vacuous)",
          True, len(_ao_entries) >= 19)
for _ent_name, _ent in _ao_entries.items():
    _mdl = _ent.get("properties", {}).get("model")
    assert_eq(f"#1646 schema: agent_overrides[{_ent_name}] declares model enum sonnet/opus/haiku/fable",
              {"type": "string", "enum": ["sonnet", "opus", "haiku", "fable"]}, _mdl)
assert_eq("#1646 schema: VALID_MODELS mirrors the schema model enum",
          ("sonnet", "opus", "haiku", "fable"), _rro.VALID_MODELS)

