assert_eq("#598: a broken relative import emits the missing-leaf repo-owned edge",
          [("scripts/definitely_missing_sibling_598.py", "repo-owned")],
          [(e.target, e.klass) for e in _bi_rel])
assert_eq("#598: the guard flags the broken relative import's missing leaf on disk",
          True,
          any("missing on disk" in err for err in cwd.check_dependencies(edges=_bi_rel)))
try:
    cwd._read = lambda rel: "import cloud_writer_deps.nonexistent_leaf_598\n"
    _bi_flat = cwd._scan_python_imports("lib/test/fake-broken-flat.py")
finally:
    cwd._read = _orig_cwd_read
assert_eq("#598: a dotted import through a flat module preserves the broken leaf edge",
          True,
          any(e.klass == "repo-owned" and e.target.endswith("nonexistent_leaf_598.py")
              for e in _bi_flat))
assert_eq("#598: the guard flags the dotted-through-flat broken leaf on disk",
          True,
          any("missing on disk" in err for err in cwd.check_dependencies(edges=_bi_flat)))

# _declared_preflight_guarantees fail-closed arms: zero/two declarations,
# duplicate tokens, and malformed tokens each raise rather than silently
# widening or narrowing the authorization vocabulary.
_pg_cases = {
    "no declaration": ("#!/usr/bin/env bash\n_need git\n", "found 0"),
    "two declarations": (
        ("readonly -a _DEVFLOW_PREFLIGHT_GUARANTEES=(git)\n"
        "readonly -a _DEVFLOW_PREFLIGHT_GUARANTEES=(gh)\n"), "found 2"),
    "duplicate token": ("readonly -a _DEVFLOW_PREFLIGHT_GUARANTEES=(git git)\n",
                        "duplicate token"),
    "malformed token": ("readonly -a _DEVFLOW_PREFLIGHT_GUARANTEES=(g!t)\n",
                        "malformed token"),
    "empty declaration": ("readonly -a _DEVFLOW_PREFLIGHT_GUARANTEES=( )\n",
                          "empty _DEVFLOW_PREFLIGHT_GUARANTEES"),
}
for _pg_name, (_pg_src, _pg_want) in _pg_cases.items():
    with tempfile.TemporaryDirectory() as _pg_tmp:
        _pg_root = Path(_pg_tmp)
        (_pg_root / "lib").mkdir()
        (_pg_root / "lib/preflight.sh").write_text(_pg_src, encoding="utf-8")
        _pg_orig_root = cwd.REPO_ROOT
        try:
            cwd.REPO_ROOT = _pg_root
            try:
                cwd._declared_preflight_guarantees()
                _pg_msg = "<no raise>"
            except RuntimeError as _pg_exc:
                _pg_msg = str(_pg_exc)
        finally:
            cwd.REPO_ROOT = _pg_orig_root
        # Pin the ARM's own diagnostic, not merely that some RuntimeError fired
        # (attribute the rejection — guard-class shape 3).
        assert_eq(f"#598: _declared_preflight_guarantees fails closed on {_pg_name} with its arm's diagnostic",
                  (True, True), (_pg_msg != "<no raise>", _pg_want in _pg_msg))

# The poison sentinel can never satisfy the co-binding acceptance predicate —
# pins the in-band "<rebound>" marker against a future widening of the
# accepted-value set.
assert_eq("#598: the '<rebound>' poison sentinel never proves a helper dir",
          (False, False),
          (cwd._helper_dir_value("<rebound>"), "<rebound>".strip() == "$(pwd)"))

# The resolve_error exception arm fails closed with its OWN diagnostic (never
# the symlink-escape diagnosis for a condition that was not established).
_orig_resolve_598 = Path.resolve
def _boom_resolve_598(self, *a, **k):
    if "resolve-boom-598" in str(self):
        raise OSError("boom-598")
    return _orig_resolve_598(self, *a, **k)
try:
    Path.resolve = _boom_resolve_598
    _re_errors = cwd.check_dependencies(edges=[
        cwd.Edge("scripts/x-598.sh", "source", "scripts/resolve-boom-598.sh", "repo-owned")])
finally:
    Path.resolve = _orig_resolve_598
assert_eq("#598: a Path.resolve() exception draws the fail-closed could-not-be-resolved arm",
          (1, True, False),
          (len(_re_errors),
           "could not be resolved" in _re_errors[0],
           "symlink escape" in _re_errors[0]))

# _profile_grant_auth fail-closed passthrough: a helper granted in no profile
# yields None, which leaves auth=None on the edge and the guard rejects it.
assert_eq("#598: _profile_grant_auth returns None for a helper in no cloud profile",
          None, cwd._profile_grant_auth("scripts/not-in-any-profile-598.sh"))

# Synthetic-edge mode skips forward-verification by contract: an injected exec
# edge whose target is absent from any source produces ONLY its own intended
# violation, never a spurious "not found in source" (the live-only gate the
# injection proofs depend on).
_syn_errors = cwd.check_dependencies(edges=[
    cwd.Edge("scripts/ghost-helper-598.sh", "exec", "made-up-binary-598", "external", None)])
assert_eq("#598: synthetic exec edge yields only its intended violation (no forward-verify)",
          (1, True, False),
          (len(_syn_errors),
           "names no preflight guarantee" in _syn_errors[0],
           any("not found in source" in err for err in _syn_errors)))

# Duck-typed edge validation mirrors the guard-relevant Edge invariants: a
# synthetic repo-owned edge smuggling an authorization string is rejected by the
# guard itself, not only by Edge.__post_init__.
_duck_errors = cwd.check_dependencies(edges=[types.SimpleNamespace(
    helper="scripts/duck-598.sh", kind="source", target="lib/resolve-jq.sh",
    klass="repo-owned", auth="smuggled-authorization")])
assert_eq("#598: the guard rejects a duck-typed repo-owned edge carrying authorization",
          True,
          any("carries external authorization" in err for err in _duck_errors))

# AC18 — 17-class rejection matrix against an isolated fixture.
with tempfile.TemporaryDirectory() as _cw_base:
    _base = Path(_cw_base)
    (_base / "scripts").mkdir()
    _asset = _base / "scripts" / "foo.sh"
    _asset.write_text("echo hi\n", encoding="utf-8")
    _good_hash = hashlib.sha256(b"echo hi\n").hexdigest()
    _head = ".prflow/vendor/prflow/scripts/foo.sh"

    def _valid_manifest():
        return {
            "protocol": "devflow-cloud-writer-contract-v1",
            "legacy_profile_baseline": "2.30.100",
            "files": {"scripts/foo.sh": _good_hash},
            "required_helper_heads": {"implement": [_head]},
        }

    def _run(manifest_obj=None, *, raw=None, path=None,
             expected_assets=("scripts/foo.sh",),
             required_profiles=("implement",),
             profile_grants=None):
        if profile_grants is None:
            profile_grants = {"implement": {_head}}
        mpath = _base / "manifest.json" if path is None else path
        if path is None:
            if raw is not None:
                mpath.write_text(raw, encoding="utf-8")
            else:
                mpath.write_text(json.dumps(manifest_obj), encoding="utf-8")
        return vcwc.validate(
            mpath, base_dir=_base,
            expected_assets=list(expected_assets),
            required_profiles=list(required_profiles),
            profile_grants=profile_grants,
        )

    # Positive control: a valid manifest yields zero violations.
    assert_eq("#543 AC18 valid: no violations", [], _run(_valid_manifest()))

    # 1 ABSENT_FILE
    assert_eq("#543 AC18 c1 ABSENT_FILE", [vcwc.ABSENT_FILE],
              _codes(_run(path=_base / "nope.json")))
    # 2 UNREADABLE_FILE (a directory is present-but-unreadable-as-text → OSError arm)
    assert_eq("#543 AC18 c2 UNREADABLE_FILE", [vcwc.UNREADABLE_FILE],
              _codes(_run(path=_base / "scripts")))
    # #578: the other UNREADABLE_FILE arm — a present file that is not valid UTF-8
    # (the UnicodeDecodeError path, distinct from the directory/OSError path above).
    _bad_utf8 = _base / "bad-utf8.json"
    _bad_utf8.write_bytes(b"\xff\xfe\x00 not utf-8 \x80\x81")
    assert_eq("#578 AC18 c2 UNREADABLE_FILE (non-UTF-8 file, decode arm)",
              [vcwc.UNREADABLE_FILE], _codes(_run(path=_bad_utf8)))
    # 3 INVALID_JSON
    assert_eq("#543 AC18 c3 INVALID_JSON", [vcwc.INVALID_JSON],
              _codes(_run(raw="{ not json")))
    # 4 TOP_LEVEL_ARRAY
    assert_eq("#543 AC18 c4 TOP_LEVEL_ARRAY", [vcwc.TOP_LEVEL_ARRAY],
              _codes(_run(raw="[]")))
    # 5 TOP_LEVEL_STRING
    assert_eq("#543 AC18 c5 TOP_LEVEL_STRING", [vcwc.TOP_LEVEL_STRING],
              _codes(_run(raw='"hi"')))
    # 6 TOP_LEVEL_FALSE (valid-falsy)
    assert_eq("#543 AC18 c6 TOP_LEVEL_FALSE", [vcwc.TOP_LEVEL_FALSE],
              _codes(_run(raw="false")))
    # 7 MISSING_KEY
    _m = _valid_manifest()
    del _m["protocol"]
    assert_eq("#543 AC18 c7 MISSING_KEY", True, vcwc.MISSING_KEY in _codes(_run(_m)))
    # 8 EXTRA_KEY
    _m = _valid_manifest()
    _m["bogus"] = 1
    assert_eq("#543 AC18 c8 EXTRA_KEY", [vcwc.EXTRA_KEY], _codes(_run(_m)))
    # 9 DUPLICATE_KEY (only expressible in raw source)
    _dup = ('{"protocol":"devflow-cloud-writer-contract-v1","protocol":"x",'
            '"legacy_profile_baseline":"2.30.100","files":{},'
            '"required_helper_heads":{}}')
    assert_eq("#543 AC18 c9 DUPLICATE_KEY", [vcwc.DUPLICATE_KEY], _codes(_run(raw=_dup)))
    # 10 WRONG_FIELD_TYPE
    _m = _valid_manifest()
    _m["files"] = "notanobject"
    assert_eq("#543 AC18 c10 WRONG_FIELD_TYPE", True,
              vcwc.WRONG_FIELD_TYPE in _codes(_run(_m)))
    # 11 MALFORMED_DIGEST
    _m = _valid_manifest()
    _m["files"] = {"scripts/foo.sh": "notahash"}
    assert_eq("#543 AC18 c11 MALFORMED_DIGEST", [vcwc.MALFORMED_DIGEST], _codes(_run(_m)))
    # 12 INVALID_PATH (escaping relative path, well-formed digest)
    _m = _valid_manifest()
    _m["files"] = {"../escape.sh": _good_hash}
    assert_eq("#543 AC18 c12 INVALID_PATH", True,
              vcwc.INVALID_PATH in _codes(_run(_m, expected_assets=())))
    # 13 MISSING_ASSET
    _m = _valid_manifest()
    _m["files"] = {"scripts/nope.sh": _good_hash}
    assert_eq("#543 AC18 c13 MISSING_ASSET", True,
              vcwc.MISSING_ASSET in _codes(_run(_m, expected_assets=("scripts/nope.sh",))))
    # 14 HASH_MISMATCH
    _m = _valid_manifest()
    _m["files"] = {"scripts/foo.sh": "0" * 64}
    assert_eq("#543 AC18 c14 HASH_MISMATCH", [vcwc.HASH_MISMATCH], _codes(_run(_m)))
    # 15 REACHED_ASSET_OMITTED
    assert_eq("#543 AC18 c15 REACHED_ASSET_OMITTED", True,
              vcwc.REACHED_ASSET_OMITTED in _codes(
                  _run(_valid_manifest(),
                       expected_assets=("scripts/foo.sh", "scripts/bar.sh"))))
    # 16 PROFILE_OMITTED
    assert_eq("#543 AC18 c16 PROFILE_OMITTED", True,
              vcwc.PROFILE_OMITTED in _codes(
                  _run(_valid_manifest(),
                       required_profiles=("implement", "review"),
                       profile_grants={"implement": {_head}, "review": set()})))
    # 17 HEAD_ABSENT
    assert_eq("#543 AC18 c17 HEAD_ABSENT", [vcwc.HEAD_ABSENT],
              _codes(_run(_valid_manifest(), profile_grants={"implement": set()})))

    # Class 10 (WRONG_FIELD_TYPE) is emitted by several distinct triggers — cover
    # the ones the single c10 fixture above did not, especially the protocol
    # identity check (the contract's own version binding).
    _m = _valid_manifest()
    _m["protocol"] = "wrong-protocol"
    assert_eq("#543 AC18 c10 protocol wrong value", True,
              vcwc.WRONG_FIELD_TYPE in _codes(_run(_m)))
    _m = _valid_manifest()
    _m["protocol"] = 5
    assert_eq("#543 AC18 c10 protocol non-string", True,
              vcwc.WRONG_FIELD_TYPE in _codes(_run(_m)))
    _m = _valid_manifest()
    _m["legacy_profile_baseline"] = 5
    assert_eq("#543 AC18 c10 legacy_profile_baseline non-string", True,
              vcwc.WRONG_FIELD_TYPE in _codes(_run(_m)))
    _m = _valid_manifest()
    _m["required_helper_heads"] = "notobj"
    assert_eq("#543 AC18 c10 required_helper_heads non-object", True,
              vcwc.WRONG_FIELD_TYPE in _codes(_run(_m)))
    _m = _valid_manifest()
    _m["required_helper_heads"] = {"implement": "notalist"}
    assert_eq("#543 AC18 c10 profile heads non-list", True,
              vcwc.WRONG_FIELD_TYPE in _codes(_run(_m)))
    assert_eq("#543 AC18 c10 top-level number (non-object scalar)",
              [vcwc.WRONG_FIELD_TYPE], _codes(_run(raw="5")))
    # Class 12 also covers an absolute (non-escaping-but-unsafe) path.
    _m = _valid_manifest()
    _m["files"] = {"/etc/passwd": _good_hash}
    assert_eq("#543 AC18 c12 absolute path", True,
              vcwc.INVALID_PATH in _codes(_run(_m, expected_assets=())))
    # Independent violations accumulate — the validator collects, it does not
    # short-circuit after the first (only fatal load/shape errors stop early).
    _m = _valid_manifest()
    _m["bogus"] = 1
    _m["files"] = {"scripts/foo.sh": "notahash"}
    _mv = _codes(_run(_m))
    assert_eq("#543 AC18 multi-violation accumulates (EXTRA_KEY + MALFORMED_DIGEST)",
              True, vcwc.EXTRA_KEY in _mv and vcwc.MALFORMED_DIGEST in _mv)

    # Every one of the 17 classes is distinct and exercised above.
    _seen = {
        vcwc.ABSENT_FILE, vcwc.UNREADABLE_FILE, vcwc.INVALID_JSON, vcwc.TOP_LEVEL_ARRAY,
        vcwc.TOP_LEVEL_STRING, vcwc.TOP_LEVEL_FALSE, vcwc.MISSING_KEY, vcwc.EXTRA_KEY,
        vcwc.DUPLICATE_KEY, vcwc.WRONG_FIELD_TYPE, vcwc.MALFORMED_DIGEST, vcwc.INVALID_PATH,
        vcwc.MISSING_ASSET, vcwc.HASH_MISMATCH, vcwc.REACHED_ASSET_OMITTED,
        vcwc.PROFILE_OMITTED, vcwc.HEAD_ABSENT,
    }
    assert_eq("#543 AC18: rejection matrix is closed at exactly 17 classes", 17, len(_seen))
    # Bind "closed at 17" to the module, not to a hand-copied literal set: the 17
    # driven classes must be exactly the module's defined rejection-code constants
    # (a NAME = "NAME" string, upper-case). An 18th class added to validate() with
    # a new constant fails this unless a matching fixture drives it into _seen.
    _module_codes = {
        v for k, v in vars(vcwc).items()
        if isinstance(v, str) and k == v and k.isupper()
    }
    assert_eq("#543 AC18: the driven classes are exactly the module's defined codes",
              _module_codes, _seen)
    # REJECTION_CODES makes "closed by construction" a structural invariant, not
    # only a docstring: it must equal both the driven set and the module constants.
    assert_eq("#543 AC18: REJECTION_CODES == the driven classes", vcwc.REJECTION_CODES, _seen)
    assert_eq("#543 AC18: REJECTION_CODES == the module's code constants",
              vcwc.REJECTION_CODES, _module_codes)
    # A nested duplicate key (inside `files`) is caught too, not only a top-level one.
    _nested_dup = ('{"protocol":"devflow-cloud-writer-contract-v1",'
                   '"legacy_profile_baseline":"2.30.100",'
                   '"files":{"a":"'+("0"*64)+'","a":"'+("1"*64)+'"},'
                   '"required_helper_heads":{}}')
    assert_eq("#543 AC18: a nested duplicate key is caught (DUPLICATE_KEY)",
              [vcwc.DUPLICATE_KEY], _codes(_run(raw=_nested_dup)))

# ─────────────────────────────────────────────────────────────────────────────
# PR #578 review (Suggestion 3): drive the fail-closed guard branches the healthy
# tree never exercises, so each is proven non-vacuous (it fires on the drift it
# guards, not merely returns clean on the healthy tree).
# ─────────────────────────────────────────────────────────────────────────────

# validate()'s default-derivation `except` arm: a failure establishing the
# expected-contract dependencies fails closed on the manifest channel
# (broadened class-10 WRONG_FIELD_TYPE), never an uncaught traceback.
_vcwc_orig_loader = vcwc._load_contract_module
try:
    def _boom():
        raise RuntimeError("contract module unimportable")
    vcwc._load_contract_module = _boom
    _deriv = vcwc.validate("whatever.json", base_dir=SCRIPTS.parent)
    assert_eq("#578-3: a dependency-derivation failure fails closed as WRONG_FIELD_TYPE",
              [vcwc.WRONG_FIELD_TYPE], _codes(_deriv))
    assert_eq("#578-3: the derivation-failure message names the reachability contract",
              True, "could not derive" in _deriv[0].message)
finally:
    vcwc._load_contract_module = _vcwc_orig_loader

# validate() returns Violation records (self-documenting .code/.message), still
# unpackable as (code, message) — pin the type so a regression to a bare tuple
# (losing the attribute access) goes RED.
assert_eq("#578-5: validate() yields Violation records with .code/.message",
          True, isinstance(_deriv[0], vcwc.Violation) and _deriv[0].code == vcwc.WRONG_FIELD_TYPE)
# _StopValidation refuses a fatal code outside the closed matrix at the raise
# boundary (previously test-enforced only for the collected list).
try:
    vcwc._StopValidation("NOT_A_REJECTION_CODE", "x")
    assert_eq("#578-5: _StopValidation rejects an off-matrix code", True, False)
except ValueError as _exc:
    assert_eq("#578-5: _StopValidation rejects an off-matrix code at the raise boundary",
              True, "REJECTION_CODES" in str(_exc))

# _path_is_safe's backslash clause (a Windows-form separator is unsafe) is
# undriven by the manifest fixtures — drive it directly, with a positive control.
_psafe_base = Path(SCRIPTS.parent).resolve()
assert_eq("#578-3: _path_is_safe rejects a backslash separator",
          False, vcwc._path_is_safe("scripts\\foo.sh", _psafe_base))
assert_eq("#578-3: _path_is_safe accepts a plain relative path (positive control)",
          True, vcwc._path_is_safe("scripts/foo.sh", _psafe_base))

# check_closure()'s on-disk / invalid-token / unknown-source / unclassified-root
# branches — monkeypatch one module global into the failing shape at a time and
# restore, asserting the specific branch fires (not merely that something did).
_cc_o_roots = cwc.ROOTS
_cc_o_edges = cwc.DISPATCH_EDGES
_cc_o_assets = cwc.SKILL_ASSETS
_cc_o_heads = cwc.REQUIRED_HELPER_HEADS
try:
    # (a) a root whose entry_skill is not classified (REQUIRED_HELPER_HEADS is
    #     widened to the same profile set so the profile-mismatch branch does not
    #     mask the entry_skill branch under test).
    cwc.ROOTS = {**_cc_o_roots,
                 "bogusroot": {"workflow": ".github/workflows/x.yml",
                               "entry_skill": "unclassified-578-skill"}}
    cwc.REQUIRED_HELPER_HEADS = {**_cc_o_heads, "bogusroot": []}
    assert_eq("#578-3: check_closure catches an unclassified root entry_skill",
              True, any("unclassified-578-skill" in e for e in cwc.check_closure()))
    cwc.ROOTS = _cc_o_roots
    cwc.REQUIRED_HELPER_HEADS = _cc_o_heads

    # (b) a classified asset that does not exist on disk.
    cwc.SKILL_ASSETS = {**_cc_o_assets,
                        "implement": _cc_o_assets["implement"]
                        + ["skills/implement/phases/does-not-exist-578.md"]}
    assert_eq("#578-3: check_closure catches a classified asset missing on disk",
              True, any("does-not-exist-578" in e and "missing on disk" in e
                        for e in cwc.check_closure()))
    cwc.SKILL_ASSETS = _cc_o_assets

    # (c) a required helper token missing the vendor prefix (ValueError arm).
    cwc.REQUIRED_HELPER_HEADS = {**_cc_o_heads,
                                 "implement": _cc_o_heads["implement"]
                                 + ["not-a-vendor-token-578.sh"]}
    assert_eq("#578-3: check_closure catches a helper token missing the vendor prefix",
              True, any("helper token invalid" in e for e in cwc.check_closure()))
    cwc.REQUIRED_HELPER_HEADS = _cc_o_heads

    # (d) a required helper whose (vendor-prefixed) source is absent on disk.
    cwc.REQUIRED_HELPER_HEADS = {**_cc_o_heads,
                                 "implement": _cc_o_heads["implement"]
                                 + [".prflow/vendor/prflow/scripts/nonexistent-578.sh"]}
    assert_eq("#578-3: check_closure catches a required helper source missing on disk",
              True, any("nonexistent-578" in e and "missing on disk" in e
                        for e in cwc.check_closure()))
    cwc.REQUIRED_HELPER_HEADS = _cc_o_heads

    # (e) a dispatch edge whose source is neither a classified skill nor a root id.
    cwc.DISPATCH_EDGES = _cc_o_edges + [{"from": "ghost-source-578", "to": "review",
                                         "kind": "nested"}]
    assert_eq("#578-3: check_closure catches a dispatch edge with an unknown source",
              True, any("ghost-source-578" in e and "unknown" in e
                        for e in cwc.check_closure()))
    cwc.DISPATCH_EDGES = _cc_o_edges
finally:
    cwc.ROOTS = _cc_o_roots
    cwc.DISPATCH_EDGES = _cc_o_edges
    cwc.SKILL_ASSETS = _cc_o_assets
    cwc.REQUIRED_HELPER_HEADS = _cc_o_heads

# main()'s check / generate / verify arms, and the generate/verify closure gate
# (Suggestion 4): a closure `check` would reject fails cleanly instead of
# crashing in build_manifest(). All manifest writes target a temp path, never the
# checked-in manifest.
assert_eq("#578-3: main(['check']) returns 0 on the healthy closure", 0, cwc.main(["check"]))
_mp_orig = cwc.MANIFEST_PATH
with tempfile.TemporaryDirectory() as _cw_main:
    _tmp_manifest = str(Path(_cw_main) / "gen.json")
    try:
        cwc.MANIFEST_PATH = _tmp_manifest
        assert_eq("#578-3: main(['generate']) returns 0 and writes the manifest", 0,
                  cwc.main(["generate"]))
        _written = Path(_tmp_manifest).read_text(encoding="utf-8")
        assert_eq("#578-3: generated manifest equals canonical_json(build_manifest())",
                  cwc.canonical_json(cwc.build_manifest()), _written)
        assert_eq("#578-3: main(['verify']) returns 0 against the fresh temp manifest",
                  0, cwc.main(["verify"]))
        Path(_tmp_manifest).write_text("stale not the manifest\n", encoding="utf-8")
        assert_eq("#578-3: main(['verify']) returns 1 on a stale manifest", 1,
                  cwc.main(["verify"]))
        cwc.MANIFEST_PATH = str(Path(_cw_main) / "absent.json")
        assert_eq("#578-3: main(['verify']) returns 1 when the manifest is absent", 1,
                  cwc.main(["verify"]))
        # generate/verify closure gate: a bad helper token makes both fail cleanly
        # (rc 1 with the check-style report) rather than crash in manifest_file_paths.
        cwc.MANIFEST_PATH = str(Path(_cw_main) / "unused.json")
        _mg_heads = cwc.REQUIRED_HELPER_HEADS
        try:
            cwc.REQUIRED_HELPER_HEADS = {**_mg_heads,
                                         "implement": _mg_heads["implement"]
                                         + ["not-a-vendor-token-578.sh"]}
            assert_eq("#578-3+4: main(['generate']) fails closed (rc 1) on a bad closure",
                      1, cwc.main(["generate"]))
            assert_eq("#578-3+4: the bad closure did not write the manifest",
                      False, Path(cwc.MANIFEST_PATH).exists())
            assert_eq("#578-3+4: main(['verify']) fails closed (rc 1) on a bad closure",
                      1, cwc.main(["verify"]))
        finally:
            cwc.REQUIRED_HELPER_HEADS = _mg_heads
    finally:
        cwc.MANIFEST_PATH = _mp_orig


# ─────────────────────────────────────────────────────────────────────────────
# issue #703 (deferred from #678): cloud-writer one-version upgrade-skew (AC19)
# and consumer-provisioning (AC20) fixtures.
#
# These fixtures drive the AC18 pre-agent validator (vcwc) and the AC1 closure
# contract (cwc) IN-PROCESS — every check calls an imported module, so NO fixture
# executes repo-root helper code (AC19's constraint), consistent with the AC18
# block above (which routes everything through vcwc/cwc too).
# ─────────────────────────────────────────────────────────────────────────────

_REPO = cwc.REPO_ROOT

# The operator-facing refresh action AC19 requires the upgrade docs to state. This
# literal is COUPLED to docs/internal/install.md's cloud-writer upgrade note — the pairing-1
# fixture below asserts the sentence is present there, so a docs reword that drops
# it turns this block RED (the two are one edit).
_CW_REFRESH_ACTION = ("refresh your installed workflows and vendored plugin content "
                      "together before your next cloud-writer run")

# Frozen legacy profile grants — the vendored helper heads each cloud profile
# granted at `legacy_profile_baseline` (cwc.LEGACY_PROFILE_BASELINE, "2.31.16"),
# the immediately-preceding supported profile set. This is a DELIBERATE frozen
# snapshot (an enforcement constant, not a live read): pairing 2 below validates
# the LIVE checked-in manifest against it, so a future PR that adds a newly-
# required helper head the frozen baseline never granted turns pairing 2 RED —
# forcing a conscious re-snapshot here in lockstep with the baseline bump, rather
# than the compatibility window silently widening. The snapshot is self-checking:
# if it omits any head the current manifest requires, pairing 2 goes RED
# (HEAD_ABSENT) at the desk. Prefix helpers keep the vendored-literal form exact.
def _cwv(_n):
    return cwc.VENDOR_PREFIX + "scripts/" + _n


def _cwl(_n):
    return cwc.VENDOR_PREFIX + "lib/" + _n

_FROZEN_LEGACY_GRANTS = {
    "implement": {
        _cwv("run-jq.sh"), _cwv("config-get.sh"), _cwv("workpad.py"),
        _cwv("parse-acs.py"), _cwv("branch-for-issue.py"),
        _cwv("update-branch-checkpoint.sh"), _cwv("resolve-existing-pr.sh"),
        _cwv("file-deferrals.py"),
        _cwv("discover-deferral-manifests.py"), _cwv("match-deferrals.py"),
        _cwv("resolve-review-overrides.py"), _cwv("apply-labels.sh"),
        _cwv("ensure-label.sh"), _cwv("apply-issue-dependencies.py"),
        _cwv("stale-prose-lint.py"),
        _cwv("dismiss-stale-rejections.sh"), _cwv("match-lint-adjudications.py"),
        _cwv("load-prompt-extension.sh"), _cwv("render-prompt-extension.sh"),
        _cwv("react-to-trigger.sh"),
        _cwv("extract-doc-needed-paths.sh"), _cwl("efficiency-trace.sh"),
    },
    "light-command": {
        _cwv("run-jq.sh"), _cwv("config-get.sh"), _cwv("workpad.py"),
        _cwv("parse-acs.py"), _cwv("branch-for-issue.py"),
        _cwv("update-branch-checkpoint.sh"), _cwv("file-deferrals.py"),
        _cwv("match-deferrals.py"), _cwv("match-lint-adjudications.py"),
        _cwv("resolve-review-overrides.py"), _cwv("stale-prose-lint.py"),
        _cwv("dismiss-stale-rejections.sh"), _cwv("load-prompt-extension.sh"),
        _cwv("render-prompt-extension.sh"),
        _cwl("efficiency-trace.sh"),
    },
    "review": {
        _cwv("run-jq.sh"), _cwv("match-deferrals.py"),
        _cwv("match-lint-adjudications.py"), _cwv("dismiss-stale-rejections.sh"),
        _cwv("workpad.py"), _cwv("config-get.sh"),
        _cwv("load-prompt-extension.sh"), _cwv("render-prompt-extension.sh"),
        _cwv("resolve-review-overrides.py"),
        _cwv("stale-prose-lint.py"), _cwl("efficiency-trace.sh"),
    },
}

# The frozen snapshot must name exactly the three cloud ROOTS profiles, so a
# fourth cloud profile added to ROOTS forces a frozen entry here rather than
# silently escaping the skew guard.
assert_eq("#703 AC19: frozen legacy profiles == the cloud ROOTS profile set",
          set(cwc.ROOTS), set(_FROZEN_LEGACY_GRANTS))

# ── AC19 pairing 1: NEW workflow + immediately-preceding PLUGIN → stops at AC18.
# Model the one-version step as a retired helper: the plugin (old) still requires
# it, the new workflow no longer grants it. This is the natural asymmetry that
# makes pairing 1 STOP while pairing 2 (below) COMPLETES — the new version dropped
# a helper, so the old plugin requires a head the new grants lack. The stop is an
# EXISTING rejection class (HEAD_ABSENT), mirroring the validator's closed matrix.
with tempfile.TemporaryDirectory() as _sk_base:
    _skb = Path(_sk_base)
    (_skb / "scripts").mkdir()
    (_skb / "scripts" / "kept-703.sh").write_text("echo hi\n", encoding="utf-8")
    (_skb / "scripts" / "retired-703.sh").write_text("echo bye\n", encoding="utf-8")
    _kept_head = ".prflow/vendor/prflow/scripts/kept-703.sh"
    _retired_head = ".prflow/vendor/prflow/scripts/retired-703.sh"
    _old_plugin_manifest = {
        "protocol": "devflow-cloud-writer-contract-v1",
        # the OLD plugin declares its own (older) baseline — the plugin contract state
        "legacy_profile_baseline": "2.15.12",
        "files": {
            "scripts/kept-703.sh": hashlib.sha256(b"echo hi\n").hexdigest(),
            "scripts/retired-703.sh": hashlib.sha256(b"echo bye\n").hexdigest(),
        },
        "required_helper_heads": {"implement": [_kept_head, _retired_head]},
    }
    _omp = _skb / "manifest.json"
    _omp.write_text(json.dumps(_old_plugin_manifest), encoding="utf-8")
    # the NEW workflow no longer grants the retired head — the workflow contract state
    _new_workflow_grants = {"implement": {_kept_head}}
    _p1 = vcwc.validate(
        _omp, base_dir=_skb,
        expected_assets=["scripts/kept-703.sh", "scripts/retired-703.sh"],
        required_profiles=["implement"],
        profile_grants=_new_workflow_grants,
    )
    # Stops at AC18, and ONLY via HEAD_ABSENT: the files exist, hashes match, and
    # both reached assets are present, so the sole violation is the ungranted head.
    assert_eq("#703 AC19 pairing1: new-workflow + old-plugin stops at AC18 (HEAD_ABSENT only)",
              [vcwc.HEAD_ABSENT], _codes(_p1))
    # The diagnostic names the PLUGIN contract state (the still-required retired head)…
    assert_eq("#703 AC19 pairing1: the AC18 diagnostic names the plugin-required retired head",
              True, any(_retired_head in _msg for _code, _msg in _p1))
    # …and the WORKFLOW contract state is the skew the fixture models: the new
    # workflow's grants (_new_workflow_grants above) drop the retired head, which
    # is why the plugin-required head is now ungranted. That asymmetry IS the
    # HEAD_ABSENT stop asserted above — no separate assertion, which would only
    # re-check the fixture's own literal grant set.

# The operator-facing refresh action + both-contract-state framing live in the
# upgrade docs (the surface a deploying consumer actually reads). AC19 requires
# them; assert the docs carry the refresh action and name both contract states
# (the pre-agent validator and the manifest's declared baseline).
_install_md = (_REPO / "docs" / "internal" / "install.md").read_text(encoding="utf-8")
assert_eq("#703 AC19: install.md states the refresh action for a below-baseline consumer",
          True, _CW_REFRESH_ACTION in _install_md)
assert_eq("#703 AC19: install.md names both contract states (validator + legacy_profile_baseline)",
          True, ("validate-cloud-writer-contract.py" in _install_md
                 and "legacy_profile_baseline" in _install_md))

# ── AC19 pairing 2: immediately-preceding WORKFLOW + NEW plugin → completes.
# Validate a freshly generated manifest (the new plugin; issue #1445 — main is the sole
# writer of the committed manifest, so a feature branch is validated against the manifest
# main would publish, never the possibly-stale committed one) under the FROZEN legacy
# grants (the immediately-preceding workflow). It completes because the current
# plugin requires no head the legacy baseline did not already grant.
_live_manifest = Path(_fresh_manifest_1445)
_p2 = vcwc.validate(
    _live_manifest, base_dir=_REPO,
    expected_assets=cwc.manifest_file_paths(),
    required_profiles=list(cwc.ROOTS),
    profile_grants={p: set(h) for p, h in _FROZEN_LEGACY_GRANTS.items()},
)
assert_eq("#703 AC19 pairing2: old-workflow (frozen legacy) + new-plugin completes cleanly",
          [], _p2)
# Non-vacuous: the guard FAILS on a newly-required denied head. Drop one head from
# a frozen profile and confirm the live manifest's requirement is now unmet — this
# is exactly the "test fails on a newly required denied head" tripwire.
_shrunk_grants = {p: set(h) for p, h in _FROZEN_LEGACY_GRANTS.items()}
_shrunk_grants["implement"].discard(_cwv("workpad.py"))
_p2neg = vcwc.validate(
    _live_manifest, base_dir=_REPO,
    expected_assets=cwc.manifest_file_paths(),
    required_profiles=list(cwc.ROOTS),
    profile_grants=_shrunk_grants,
)
assert_eq("#703 AC19 pairing2: a newly-required head absent from the frozen profile is caught",
          True, vcwc.HEAD_ABSENT in _codes(_p2neg))
# The "or shape" half: no AC1-reached fence emits a denied shape under the
# probe-anchored tables (unchanged since the baseline), so the new plugin also
# introduces no newly-denied command shape.
assert_eq("#703 AC19 pairing2: no AC1-reached fence emits a denied shape (the 'or shape' half)",
          [], cwc.check_shape_conformance())

# ─────────────────────────────────────────────────────────────────────────────
# issue #1445: the cloud-writer manifest is a merge chokepoint no more. `main` is its
# sole writer (version-consolidate.yml), no feature branch regenerates it, and a CI-side
# merge-base check catches a hand-authored branch mutation. The seven acceptance criteria
# are exercised end to end below.
# ─────────────────────────────────────────────────────────────────────────────
import hashlib as _h1445

_regen1445 = _load('regenerate_artifacts_1445', _LIBTEST / 'regenerate-artifacts.py')
_cwr1445 = _load('cloud_writer_retention_1445', _LIBTEST / 'cloud-writer-retention-check.py')


def _git1445_raw(cwd, *args):
    return _subprocess.run(('git',) + args, cwd=cwd, capture_output=True, text=True)


def _git1445(cwd, *args):
    # Raise on a failed fixture step: a failed checkout leaves two branch names on one
    # commit, where merge-tree reports clean and every "no conflict" arm passes vacuously.
    r = _git1445_raw(cwd, *args)
    if r.returncode != 0:
        raise AssertionError(
            f"#1445 fixture: git {' '.join(args)} failed rc={r.returncode}:"
            f" {(r.stderr or '').strip()}")
    return r


def _sha1445(text):
    return _h1445.sha256(text.encode('utf-8')).hexdigest()


def _canon1445(files):
    # Canonical one-key-per-line JSON, matching cwc.canonical_json's shape, so adjacent
    # manifest entries land on adjacent lines exactly as the real artifact does.
    return json.dumps({"files": files}, sort_keys=True, indent=2, ensure_ascii=False) + "\n"


def _mt_conflict1445(repo, ref_a, ref_b):
    # rc 0 is a clean merge and rc 1 a conflict; any OTHER rc is a git or usage error
    # (an older git without --write-tree, a bad ref) and must not be read as "conflict",
    # or the discriminating controls below pass green while measuring nothing.
    r = _git1445_raw(repo, 'merge-tree', '--write-tree', ref_a, ref_b)
    if r.returncode not in (0, 1):
        raise AssertionError(
            f"#1445 fixture: git merge-tree --write-tree errored rc={r.returncode}"
            f" (needs git >= 2.38): {(r.stderr or '').strip()}")
    return r.returncode == 1 or 'CONFLICT' in r.stdout or 'CONFLICT' in r.stderr


# ── AC7 (branch-side): the batched artifact-regeneration pass does not write the manifest.
_regen_writes_1445 = [
    w for row in _regen1445.ROWS
    for w in ((row.get("writes"),) if isinstance(row.get("writes"), str) else tuple(row.get("writes") or ()))
]
assert_eq("#1445 AC7: no regenerate-artifacts.py row writes the cloud-writer manifest",
          False, _regen1445.MECHANICAL_ARTIFACT in _regen_writes_1445)
assert_eq("#1445 AC7: no regenerate-artifacts.py row is named cloud-writer-manifest",
          False, "cloud-writer-manifest" in [r["name"] for r in _regen1445.ROWS])
# emit_list output (the coordinator/batched-pass consumer surface) never names it either.
_regen_list_1445 = _subprocess.run(
    ('python3', 'lib/test/regenerate-artifacts.py', '--list'),
    cwd=str(_REPO), capture_output=True, text=True)
# Establish the output before reading an ABSENCE from it: a crashing --list emits empty
# stdout, in which the absence assertion below passes while proving nothing about the rows.
# Name a row that must be present: a header-only substring would also survive a partial crash.
assert_eq("#1445 AC7: --list exits 0 and emits a known row (control for the absence assertion)",
          True, _regen_list_1445.returncode == 0
          and _regen1445.ROWS[0]["name"] in _regen_list_1445.stdout)
assert_eq("#1445 AC7: --list emits no cloud-writer-manifest row",
          False, "cloud-writer-manifest" in _regen_list_1445.stdout)

# ── AC3 check 1: the published digests are derived from the live bytes of the SAME tree.
# build_manifest() hashes each pinned path's current bytes, so every digit matches a fresh
# sha256 of that path — the derivation-from-live-bytes property version-consolidate.yml
# relies on (it runs `generate` against the merged tree immediately before its commit).
_bm1445 = cwc.build_manifest()


def _sha_bytes1445(rel):
    # Hash independently of cwc.sha256_of: comparing the generator against the very helper
    # it calls is a tautology that a mutant inside that helper would survive.
    return _h1445.sha256((_REPO / rel).read_bytes()).hexdigest()


assert_eq("#1445 AC3.1: every published digest is the sha256 of the live file bytes",
          True, all(_bm1445["files"][p] == _sha_bytes1445(p) for p in cwc.manifest_file_paths()))
# The publishing step regenerates from the tree BEFORE it commits (so the digests derive
# from the exact bytes the commit ships), and stages the artifact explicitly.
_vc_yml_1445 = (_REPO / ".github" / "workflows" / "version-consolidate.yml").read_text(encoding="utf-8")
_gen_idx_1445 = _vc_yml_1445.find("cloud_writer_contract.py generate")
_commit_idx_1445 = _vc_yml_1445.find('git commit -m "chore: bump version')
_reset_idx_1445 = _vc_yml_1445.find("git reset --hard origin/")
# Bound the regeneration on BOTH sides: above the reset it is discarded, below the commit it
# never ships, and either mutant satisfies a commit-side-only ordering check.
assert_eq("#1445 AC3.1: version-consolidate.yml regenerates the manifest after its reset and before its commit",  # structural-pin-ok: cross-file-phase-contract -- the main-side publish must regenerate from the merged tree after the reset that establishes it and before committing, or the published digests do not derive from the bytes they ship
          True, 0 <= _reset_idx_1445 < _gen_idx_1445 < _commit_idx_1445)
assert_eq("#1445 AC3.1: version-consolidate.yml stages the regenerated manifest",
          True, "git add scripts/devflow-cloud-writer-contract.json" in _vc_yml_1445)
# The branch-side half of AC3.2/AC7 is the CI invocation of the mutation check; pin that
# ci.yml actually wires it, so deleting the step (silently dropping the only branch-side
# guard) turns the suite RED rather than passing on the check's own unit tests alone.
_ci_yml_1445 = (_REPO / ".github" / "workflows" / "ci.yml").read_text(encoding="utf-8")
assert_eq("#1445 AC3.2/AC7: ci.yml wires the cloud-writer mutation check into the lint job",  # structural-pin-ok: routing-dispatch-contract -- the CI step is the sole branch-side enforcement of the merge-base mutation check; without it the guard vanishes silently
          True, "python3 lib/test/cloud-writer-retention-check.py" in _ci_yml_1445)

# ── AC3 check 2 / AC7 (main-side protection): the merge-base mutation check.
# Pure-core arms (no git): unchanged → clean; a mutation against a SOUND comparand → exit 1;
# the same difference against a SUBSTITUTED comparand → unestablished (exit 3), acknowledgeable.
_cwr_base_1445 = {"files": {"skills/x/SKILL.md": "aa"}}
_cwr_head_same_1445 = {"files": {"skills/x/SKILL.md": "aa"}}
_cwr_head_diff_1445 = {"files": {"skills/x/SKILL.md": "bb"}}
assert_eq("#1445 AC3.2: retention core reports no violation for an unchanged manifest",
          [], _cwr1445.detect_mutation(_cwr_base_1445, _cwr_head_same_1445))
_cwr_viol_1445 = _cwr1445.detect_mutation(_cwr_base_1445, _cwr_head_diff_1445)
assert_eq("#1445 AC3.2: retention core reports a violation for a mutated manifest",
          1, len(_cwr_viol_1445))
assert_eq("#1445 AC3.2: a mutation against a sound comparand exits 1 (mutated)",
          _cwr1445.EXIT_MUTATED,
          _cwr1445.classify_outcome(_cwr_viol_1445, [], False, "origin/main", False)[0])
assert_eq("#1445 AC3.2: a mutation against a substituted comparand is unestablished (exit 3)",
          _cwr1445.EXIT_UNESTABLISHED,
          _cwr1445.classify_outcome(_cwr_viol_1445, ["shallow"], False, "origin/main", True)[0])
assert_eq("#1445 AC3.2: --allow-degraded-base acknowledges the substituted comparand (exit 0)",
          _cwr1445.EXIT_CLEAN,
          _cwr1445.classify_outcome(_cwr_viol_1445, ["shallow"], True, "origin/main", True)[0])
assert_eq("#1445 AC3.2: a clean comparand exits 0",
          _cwr1445.EXIT_CLEAN,
          _cwr1445.classify_outcome([], [], False, "origin/main", False)[0])
# #1606: only an asset-adding delta is permitted, so both arms are exercised here.
_cwr_base_1606 = {"files": {"skills/x/SKILL.md": "aa"}, "protocol": "v1"}
assert_eq("#1606: adding an asset entry is permitted (the other two checks keep full strength)",
          [], _cwr1445.detect_mutation(
              _cwr_base_1606,
              {"files": {"skills/x/SKILL.md": "aa", "skills/y/SKILL.md": "bb"}, "protocol": "v1"}))
assert_eq("#1606: dropping an existing asset entry is still a violation",
          1, len(_cwr1445.detect_mutation(
              _cwr_base_1606, {"files": {}, "protocol": "v1"})))
assert_eq("#1606: an addition that also rewrites an existing entry is still a violation",
          1, len(_cwr1445.detect_mutation(
              _cwr_base_1606,
              {"files": {"skills/x/SKILL.md": "ZZ", "skills/y/SKILL.md": "bb"}, "protocol": "v1"})))
assert_eq("#1606: an empty base asset map is not a vacuous pass (unknown is not zero)",
          1, len(_cwr1445.detect_mutation(
              {"files": {}, "protocol": "v1"},
              {"files": {"skills/x/SKILL.md": "aa"}, "protocol": "v1"})))
assert_eq("#1606: a head that lost its asset map reports an unestablished comparand, not an entry change",
          True, "comparand unestablished" in _cwr1445.detect_mutation(
              {"files": {"a": "1"}, "protocol": "v1"}, {"files": None, "protocol": "v1"})[0])
assert_eq("#1606: a changed non-asset top-level key is still a violation",
          1, len(_cwr1445.detect_mutation(
              _cwr_base_1606, {"files": {"skills/x/SKILL.md": "aa"}, "protocol": "v2"})))
# detect_mutation's fail-closed arms: a non-object base or head is a comparand-unestablished
# violation, never silently read as 'unchanged' (the docstring's "drives every arm" claim).
assert_eq("#1445 AC3.2: a non-object base manifest is flagged (fail closed, not 'unchanged')",
          1, len(_cwr1445.detect_mutation("not-a-dict", {"files": {}})))
assert_eq("#1445 AC3.2: a non-object head manifest is flagged (fail closed, not 'unchanged')",
          1, len(_cwr1445.detect_mutation({"files": {}}, ["not-a-dict"])))
# classify_outcome's unestablished-WITHOUT-violations arm: a shallow clone whose manifest
# happens to match the substitute tip is still not clean (unknown is not zero) — exit 3, and
# exit 0 only when the degraded base is explicitly acknowledged.
assert_eq("#1445 AC3.2: unestablished base with no difference is still not clean (exit 3)",
          _cwr1445.EXIT_UNESTABLISHED,
          _cwr1445.classify_outcome([], ["shallow"], False, "origin/main", True)[0])
assert_eq("#1445 AC3.2: --allow-degraded-base acknowledges an unchanged-but-degraded base (exit 0)",
          _cwr1445.EXIT_CLEAN,
          _cwr1445.classify_outcome([], ["shallow"], True, "origin/main", True)[0])
# Arm ORDER, asserted directly (the docstring's "arm order is load-bearing" claim): with a
# SOUND comparand, arm 1 must win over arm 2 even when unestablished reasons are present —
# exit 1, not 3, and no acknowledgement flag can downgrade it. main() cannot construct this
# combination (its only `unestablished` source also sets comparand_substituted), so the pure
# core is the sole way to prove the precedence.
_cwr_arm1_1445 = _cwr1445.classify_outcome(
    _cwr_viol_1445, ["some unrelated unestablished reason"], False, "origin/main", False)
assert_eq("#1445 AC3.2: arm 1 precedes arm 2 — a sound-comparand mutation exits 1 despite unestablished reasons",
          _cwr1445.EXIT_MUTATED, _cwr_arm1_1445[0])
assert_eq("#1445 AC3.2: that arm-1 report appends the unestablished reasons as context",
          True, any("some unrelated unestablished reason" in ln for ln in _cwr_arm1_1445[1]))
assert_eq("#1445 AC3.2: no acknowledgement flag can downgrade an established mutation",
          _cwr1445.EXIT_MUTATED,
          _cwr1445.classify_outcome(
              _cwr_viol_1445, ["some unrelated unestablished reason"], True, "origin/main", False)[0])

# End-to-end git fixture: a branch that mutates the manifest FAILS the check; one that
# leaves it untouched PASSES — and it needs NO local git configuration to do either (AC6).
with tempfile.TemporaryDirectory(prefix='cwr1445-') as _cwr_repo_str:
    _cwr_repo = Path(_cwr_repo_str)
    _git1445(_cwr_repo, 'init', '-q', '-b', 'main')
    _git1445(_cwr_repo, 'config', 'user.email', 'a@b.c')
    _git1445(_cwr_repo, 'config', 'user.name', 'T')
    (_cwr_repo / 'scripts').mkdir()
    _man_rel_1445 = 'scripts/devflow-cloud-writer-contract.json'
    (_cwr_repo / _man_rel_1445).write_text(_canon1445({"skills/a.md": _sha1445("a")}), encoding='utf-8')
    (_cwr_repo / 'skills').mkdir()
    (_cwr_repo / 'skills' / 'a.md').write_text("a", encoding='utf-8')
    _git1445(_cwr_repo, 'add', '-A')
    _git1445(_cwr_repo, 'commit', '-qm', 'base')
    _git1445(_cwr_repo, 'branch', 'origin/main')  # local stand-in for the base ref
    # Untouched branch: edit a source file, leave the manifest alone → clean (exit 0).
    _git1445(_cwr_repo, 'checkout', '-q', '-b', 'feat-clean')
    (_cwr_repo / 'skills' / 'a.md').write_text("a changed", encoding='utf-8')
    _git1445(_cwr_repo, 'commit', '-qam', 'edit source, not the manifest')
    _rc_clean_1445 = _cwr1445.main(['x', str(_cwr_repo), '--base-ref', 'origin/main'])
    assert_eq("#1445 AC3.2 e2e: an untouched manifest passes the check (exit 0), no local config",
              _cwr1445.EXIT_CLEAN, _rc_clean_1445)
    # Mutating branch: hand-edit the manifest → mutated (exit 1).
    _git1445(_cwr_repo, 'checkout', '-q', 'main')
    _git1445(_cwr_repo, 'checkout', '-q', '-b', 'feat-mutated')
    (_cwr_repo / _man_rel_1445).write_text(_canon1445({"skills/a.md": _sha1445("tampered")}), encoding='utf-8')
    _git1445(_cwr_repo, 'commit', '-qam', 'hand-edit the manifest')
    _rc_mut_1445 = _cwr1445.main(['x', str(_cwr_repo), '--base-ref', 'origin/main'])
    assert_eq("#1445 AC3.2 e2e: a hand-mutated manifest fails the check (exit 1)",
              _cwr1445.EXIT_MUTATED, _rc_mut_1445)
    # main()'s fail-closed CLI arm: an unresolvable base ref (merge_base None) must exit
    # EXIT_MUTATED, never EXIT_CLEAN — a genuinely-unverifiable run never reports green.
    _rc_nobase_1445 = _cwr1445.main(['x', str(_cwr_repo), '--base-ref', 'origin/does-not-exist-1445'])
    assert_eq("#1445 AC3.2 e2e: an unresolvable base ref fails closed (exit 1), never clean",
              _cwr1445.EXIT_MUTATED, _rc_nobase_1445)
    # main()'s two remaining fail-closed read arms. Each carries a positive control on the
    # SAME fixture (the clean branch above already exits 0 with both manifests readable), so
    # a rejection from an unrelated precondition cannot masquerade as the arm under test.
    # Unreadable HEAD manifest: malformed JSON in the working tree → exit 1, never clean.
    _git1445(_cwr_repo, 'checkout', '-q', 'feat-clean')
    _man_backup_1445 = (_cwr_repo / _man_rel_1445).read_text(encoding='utf-8')
    (_cwr_repo / _man_rel_1445).write_text("{ not json", encoding='utf-8')
    _badhead_out_1445 = io.StringIO()
    with contextlib.redirect_stdout(_badhead_out_1445):
        _rc_badhead_1445 = _cwr1445.main(['x', str(_cwr_repo), '--base-ref', 'origin/main'])
    assert_eq("#1445 AC3.2 e2e: an unreadable HEAD manifest fails closed (exit 1), never clean",
              _cwr1445.EXIT_MUTATED, _rc_badhead_1445)
    # Attribute the rejection: this arm, not the mutation arm or an earlier precondition.
    assert_eq("#1445 AC3.2 e2e: the unreadable-HEAD rejection names the head read",
              True, "could not read the head" in _badhead_out_1445.getvalue())
    (_cwr_repo / _man_rel_1445).write_text(_man_backup_1445, encoding='utf-8')
    assert_eq("#1445 AC3.2 e2e control: the same fixture is otherwise clean (exit 0)",
              _cwr1445.EXIT_CLEAN,
              _cwr1445.main(['x', str(_cwr_repo), '--base-ref', 'origin/main']))
    # Malformed BASE manifest: the merge base carries unparseable JSON. An ABSENT path at the
    # base is deliberately the empty object (retention_check_common.git_show_json), so absence
    # alone never reaches main()'s base_error arm — malformed JSON and any other `git show`
    # failure do.
    _git1445(_cwr_repo, 'checkout', '-q', '-b', 'base-bad-manifest', 'origin/main')
    (_cwr_repo / _man_rel_1445).write_text("{ not json", encoding='utf-8')
    _git1445(_cwr_repo, 'commit', '-qam', 'malformed manifest at the base')
    _git1445(_cwr_repo, 'checkout', '-q', '-b', 'feat-off-bad-base')
    (_cwr_repo / 'skills' / 'a.md').write_text("a off bad base", encoding='utf-8')
    _git1445(_cwr_repo, 'commit', '-qam', 'branch work, manifest untouched')
    _badbase_out_1445 = io.StringIO()
    with contextlib.redirect_stdout(_badbase_out_1445):
        _rc_badbase_1445 = _cwr1445.main(
            ['x', str(_cwr_repo), '--base-ref', 'base-bad-manifest'])
    assert_eq("#1445 AC3.2 e2e: an unreadable base manifest fails closed (exit 1), never clean",
              _cwr1445.EXIT_MUTATED, _rc_badbase_1445)
    assert_eq("#1445 AC3.2 e2e: the unreadable-base rejection names the base read",
              True, "could not read the base" in _badbase_out_1445.getvalue())
    # main()'s DEGRADED-comparand branch, driven end-to-end (not by handing the pure core a
    # comparand_substituted sentinel): an unrelated-history base ref makes `git merge-base`
    # report no merge base, which is exactly the arm a shallow/partial clone takes in
    # retention_check_common.merge_base — the base ref's own tip substitutes for the merge
    # base. Without this, main()'s degraded routing and the --allow-degraded-base argparse
    # wiring could stop firing with no RED test.
    _git1445(_cwr_repo, 'checkout', '-q', '--orphan', 'unrelated-1445')
    (_cwr_repo / _man_rel_1445).write_text(
        _canon1445({"skills/a.md": _sha1445("unrelated root")}), encoding='utf-8')
    _git1445(_cwr_repo, 'add', '-A')
    _git1445(_cwr_repo, 'commit', '-qm', 'unrelated root')
    _git1445(_cwr_repo, 'checkout', '-q', 'feat-clean')
    _degraded_out_1445 = io.StringIO()
    with contextlib.redirect_stdout(_degraded_out_1445):
        _rc_degraded_1445 = _cwr1445.main(
            ['x', str(_cwr_repo), '--base-ref', 'unrelated-1445'])
    assert_eq("#1445 AC3.2 e2e: a degraded base comparand exits 3 (unestablished), never 0 or 1",
              _cwr1445.EXIT_UNESTABLISHED, _rc_degraded_1445)
    assert_eq("#1445 AC3.2 e2e: the degraded run names the substitute comparand, not a mutation",
              True, "could not be established" in _degraded_out_1445.getvalue())
    # The same invocation plus the acknowledgement flag: exit 0, and still reported as
    # acknowledged-degraded rather than as a verified clean pass.
    _ack_out_1445 = io.StringIO()
    with contextlib.redirect_stdout(_ack_out_1445):
        _rc_ack_1445 = _cwr1445.main(
            ['x', str(_cwr_repo), '--base-ref', 'unrelated-1445', _cwr1445.ACK_FLAG])
    assert_eq("#1445 AC3.2 e2e: --allow-degraded-base is wired through argparse and exits 0",
              _cwr1445.EXIT_CLEAN, _rc_ack_1445)
    assert_eq("#1445 AC3.2 e2e: the acknowledged run still reports itself as degraded",
              True, "acknowledged" in _ack_out_1445.getvalue())
    # The docstring's `main`-side claim, driven end-to-end: version-consolidate.yml's
    # legitimate rewrite is never flagged. On `main` the base ref IS the branch's own tip, so
    # the merge base is HEAD and the freshly-rewritten manifest is its own comparand.
    _git1445(_cwr_repo, 'checkout', '-q', 'main')
    (_cwr_repo / _man_rel_1445).write_text(
        _canon1445({"skills/a.md": _sha1445("regenerated on main")}), encoding='utf-8')
    _git1445(_cwr_repo, 'commit', '-qam', 'chore: bump version (manifest regenerated on main)')
    _git1445(_cwr_repo, 'branch', '-f', 'origin/main', 'HEAD')
    assert_eq("#1445 AC3.2 e2e: on `main`, the legitimate main-side rewrite is not flagged (exit 0)",
              _cwr1445.EXIT_CLEAN,
              _cwr1445.main(['x', str(_cwr_repo), '--base-ref', 'origin/main']))

# ── AC1 / AC2: two branches editing disjoint regions of the SAME pinned file (AC1) or two
# ADJACENT-sorted pinned files (AC2), each running the regeneration pass, merge into main in
# BOTH orders with no conflict — because the pass no longer rewrites the manifest. The
# discriminating control: the OLD writer (manifest rewritten per branch) DID conflict.
# Do not delete AC7 as redundant with these arms: they demonstrate a property of git given an
# untouched manifest, and AC7 is the only assertion that the pass leaves it untouched.
with tempfile.TemporaryDirectory(prefix='mt1445-') as _mt_repo_str:
    _mt_repo = Path(_mt_repo_str)
    _git1445(_mt_repo, 'init', '-q', '-b', 'main')
    _git1445(_mt_repo, 'config', 'user.email', 'a@b.c')
    _git1445(_mt_repo, 'config', 'user.name', 'T')
    (_mt_repo / 'skills').mkdir()
    # A pinned file with many lines so top/bottom edits are textually disjoint (AC1), and two
    # sibling files whose manifest entries sort adjacent (AC2 — same directory).
    _a_lines = "\n".join(f"line {i}" for i in range(1, 41)) + "\n"
    (_mt_repo / 'skills' / 'a.md').write_text(_a_lines, encoding='utf-8')
    (_mt_repo / 'skills' / 'b.md').write_text("b base\n", encoding='utf-8')
    (_mt_repo / 'skills' / 'c.md').write_text("c base\n", encoding='utf-8')
    _base_files_1445 = {
        "skills/a.md": _sha1445(_a_lines),
        "skills/b.md": _sha1445("b base\n"),
        "skills/c.md": _sha1445("c base\n"),
    }
    (_mt_repo / 'manifest.json').write_text(_canon1445(_base_files_1445), encoding='utf-8')
    _git1445(_mt_repo, 'add', '-A')
    _git1445(_mt_repo, 'commit', '-qm', 'base')

    def _branch_edit_1445(name, path, new_text, rewrite_manifest):
        _git1445(_mt_repo, 'checkout', '-q', 'main')
        _git1445(_mt_repo, 'checkout', '-q', '-b', name)
        (_mt_repo / path).write_text(new_text, encoding='utf-8')
        if rewrite_manifest:  # the OLD, rejected behavior — the branch is a manifest writer
            files = dict(_base_files_1445)
            files[path] = _sha1445(new_text)
            (_mt_repo / 'manifest.json').write_text(_canon1445(files), encoding='utf-8')
        # else: the NEW behavior — the regeneration pass leaves the manifest untouched.
        _git1445(_mt_repo, 'commit', '-qam', f'{name} edit')

    # AC1 — same file, disjoint regions (top vs bottom).
    _a_top = _a_lines.replace("line 1\n", "line 1 EDITED\n", 1)
    _a_bot = _a_lines.replace("line 40\n", "line 40 EDITED\n", 1)
    _branch_edit_1445('ac1-new-A', 'skills/a.md', _a_top, False)
    _branch_edit_1445('ac1-new-B', 'skills/a.md', _a_bot, False)
    assert_eq("#1445 AC1: same-file disjoint edits, no manifest rewrite → no conflict (order 1)",
              False, _mt_conflict1445(_mt_repo, 'ac1-new-A', 'ac1-new-B'))
    assert_eq("#1445 AC1: same-file disjoint edits, no manifest rewrite → no conflict (order 2)",
              False, _mt_conflict1445(_mt_repo, 'ac1-new-B', 'ac1-new-A'))
    # Discriminating control: the OLD writer rewrote the manifest on each side → conflict.
    _branch_edit_1445('ac1-old-A', 'skills/a.md', _a_top, True)
    _branch_edit_1445('ac1-old-B', 'skills/a.md', _a_bot, True)
    assert_eq("#1445 AC1 control: the OLD manifest-writer behavior DID conflict (test is discriminating)",
              True, _mt_conflict1445(_mt_repo, 'ac1-old-A', 'ac1-old-B'))

    # AC2 — two different pinned files whose manifest entries sort adjacent (b.md, c.md).
    _branch_edit_1445('ac2-new-A', 'skills/b.md', "b EDITED\n", False)
    _branch_edit_1445('ac2-new-B', 'skills/c.md', "c EDITED\n", False)
    assert_eq("#1445 AC2: adjacent-sorted different pinned files, no manifest rewrite → no conflict (order 1)",
              False, _mt_conflict1445(_mt_repo, 'ac2-new-A', 'ac2-new-B'))
    assert_eq("#1445 AC2: adjacent-sorted different pinned files, no manifest rewrite → no conflict (order 2)",
              False, _mt_conflict1445(_mt_repo, 'ac2-new-B', 'ac2-new-A'))
    _branch_edit_1445('ac2-old-A', 'skills/b.md', "b EDITED\n", True)
    _branch_edit_1445('ac2-old-B', 'skills/c.md', "c EDITED\n", True)
    assert_eq("#1445 AC2 control: the OLD manifest-writer behavior DID conflict on adjacent entries",
              True, _mt_conflict1445(_mt_repo, 'ac2-old-A', 'ac2-old-B'))

# ── AC4: the sorted list of pinned paths is stable — sorted, de-duplicated, and equal to the
# keys the generator writes (however it exposes the list). #1445 changes none of the inputs
# (SKILL_ASSETS / REQUIRED_HELPER_HEADS / PROTECTED_IMPORT_SOURCES) that feed it.
_paths1445 = cwc.manifest_file_paths()
assert_eq("#1445 AC4: manifest_file_paths() is sorted and de-duplicated",
          True, _paths1445 == sorted(set(_paths1445)) and len(_paths1445) > 0)
assert_eq("#1445 AC4: the artifact pins exactly the generator's exposed path list",
          _paths1445, sorted(_bm1445["files"].keys()))  # reuse the AC3.1 manifest — no second full-closure hash

# ── AC5: against the post-change (unchanged) shape, validate-cloud-writer-contract.py is
# clean for a consumer whose grants cover every required_helper_heads entry, and emits
# HEAD_ABSENT naming an uncovered head for one missing a head.
# required_helper_heads is derived from REQUIRED_HELPER_HEADS with no file I/O, so read it
# directly rather than re-hashing the whole closure via build_manifest().
_cover_grants_1445 = {p: set(h) for p, h in cwc.REQUIRED_HELPER_HEADS.items()}
_p5_clean = vcwc.validate(
    _fresh_manifest_1445, base_dir=_REPO,
    expected_assets=cwc.manifest_file_paths(),
    required_profiles=list(cwc.ROOTS),
    profile_grants=_cover_grants_1445,
)
assert_eq("#1445 AC5: validator is clean when grants cover every required_helper_heads entry",
          [], _p5_clean)
_missing_grants_1445 = {p: set(h) for p, h in _cover_grants_1445.items()}
_dropped_profile_1445 = next(p for p, h in _missing_grants_1445.items() if h)
_dropped_order_1445 = list(_missing_grants_1445[_dropped_profile_1445])
_dropped_head_1445 = _dropped_order_1445[0]
_missing_grants_1445[_dropped_profile_1445] = set(_dropped_order_1445[1:])
_p5_missing = vcwc.validate(
    _fresh_manifest_1445, base_dir=_REPO,
    expected_assets=cwc.manifest_file_paths(),
    required_profiles=list(cwc.ROOTS),
    profile_grants=_missing_grants_1445,
)
assert_eq("#1445 AC5: validator emits HEAD_ABSENT for a fixture missing a required head",
          True, vcwc.HEAD_ABSENT in _codes(_p5_missing))
# AC5 requires the diagnostic to NAME the uncovered head, not merely to carry the code: a
# HEAD_ABSENT that named the wrong head would satisfy a code-membership check alone.
assert_eq("#1445 AC5: the HEAD_ABSENT diagnostic names the uncovered head",
          True, any(code == vcwc.HEAD_ABSENT and _dropped_head_1445 in message
                    for code, message in _p5_missing))

# ── AC6: the chosen mechanism needs NO per-clone local git configuration. An executable
# check asserts no merge driver is registered for the manifest path (unlike the coverage
# map, which does need `--register`), so a fresh clone's automatic setup path needs no
# manual step. The retention e2e above already proved the check runs with no local config.
_gitattributes_1445 = (_REPO / ".gitattributes").read_text(encoding="utf-8")
assert_eq("#1445 AC6: .gitattributes registers no merge= driver for the cloud-writer manifest",
          True, not any(
              "devflow-cloud-writer-contract" in ln and "merge=" in ln
              for ln in _gitattributes_1445.splitlines()))
_cwr_src_1445 = (_LIBTEST / "cloud-writer-retention-check.py").read_text(encoding="utf-8")
assert_eq("#1445 AC6: the mutation check registers no git config (no --register / git config --local)",
          True, "--register" not in _cwr_src_1445 and "config --local" not in _cwr_src_1445)

# ── AC7 (no-config clone): the generator is deterministic and its output verifies clean with
# no local git configuration — regenerating twice yields byte-identical output, so a fresh
# clone (which registers nothing) produces exactly what `main` publishes.
assert_eq("#1445 AC7: the generator is deterministic (byte-identical across two renders)",
          cwc.canonical_json(cwc.build_manifest()), cwc.canonical_json(cwc.build_manifest()))
# AC4's before/after comparand: the checked-in artifact is main's and this PR does not modify
# it, so its key set IS the pre-change list. Read it from the tree, never from origin/<base>:
# a remote-state comparand turns RED on every branch whenever main's manifest is stale, which
# is the residual #1445 documents rather than a defect in the branch under test.
_committed_art_1445 = json.loads(
    (_REPO / "scripts" / "devflow-cloud-writer-contract.json").read_text(encoding="utf-8"))
assert_eq("#1445 AC4: the pinned path list is identical to the pre-change artifact's",
          sorted(_committed_art_1445["files"].keys()), _paths1445)

# ─────────────────────────────────────────────────────────────────────────────
# issue #703 AC20: consumer-provisioning fixtures — fresh install, in-place
# install.sh refresh, and /devflow:init backfill. Complete by construction for the
# three supported consumer setup flows: each is asserted to (a) deliver a valid
# runtime manifest, (b) preserve helper executable bits, and (c) retain
# consumer-owned config + prompt extensions. Every assertion is in-process (Reads
# source + calls imported modules) — no fixture executes repo-root helper code.
# The three supported flows are fresh-install, in-place install.sh refresh, and
# /devflow:init backfill; each is covered by its own (a)/(b)/(c) assertion groups
# below (manifest / executable-bit / consumer-content), which ARE the completeness
# coverage — no separate enumeration assertion, which would only guard its own
# literal count.
# ─────────────────────────────────────────────────────────────────────────────
_install_sh = (_REPO / "install.sh").read_text(encoding="utf-8")
_vendor_slice = (_REPO / ".github" / "actions" / "vendor-plugin"
                 / "vendor-slice.sh").read_text(encoding="utf-8")
_init_skill = (_REPO / "skills" / "init" / "SKILL.md").read_text(encoding="utf-8")
_scaffold_sh = (_REPO / "scripts" / "scaffold-config.sh").read_text(encoding="utf-8")

# (a) Runtime manifest. Fresh install and in-place refresh deliver the manifest as
# a byte-copied asset of the vendored scripts/ tree — install.sh and the vendor
# slice run NO regeneration (regeneration is a maintainer-side operation), so the
# artifact each flow delivers is exactly the checked-in one. Its internal consistency
# is guaranteed on `main` (issue #1445 moved the `verify` drift gate off this per-branch
# check onto version-consolidate.yml, which regenerates it from the merged tree before
# every bump commit); the branch-side `cwc.main(["verify"])` assertion that used to sit
# here was removed so a feature branch is never gated on a manifest it no longer writes.
# /devflow:init never touches the manifest (it preserves whatever the vendored plugin
# already carries).
assert_eq("#703 AC20: install.sh runs no manifest regeneration (byte-copies the vendored artifact)",
          False, "cloud_writer_contract.py generate" in _install_sh)
assert_eq("#703 AC20: the vendor slice runs no manifest regeneration",
          False, "cloud_writer_contract.py generate" in _vendor_slice)
assert_eq("#703 AC20: the vendor slice byte-copies the scripts/ tree (manifest arrives as an asset)",
          True, ('cp -R "$src/.claude-plugin"' in _vendor_slice
                 and '"$src/scripts"' in _vendor_slice))
assert_eq("#703 AC20: /devflow:init never touches the runtime manifest (preserves the vendored copy)",
          True, ("cloud_writer_contract" not in _init_skill
                 and "devflow-cloud-writer-contract" not in _init_skill))

# (b) Executable bits. `cp -R` preserves file modes by default (it only strips
# them under `--no-preserve=mode`), so helper executable bits survive a copy by
# construction — the contract is that install.sh and the vendor slice use a plain
# mode-preserving `cp -R` and never pass `--no-preserve`. Two exec-bit surfaces:
# the vendor slice's `cp -R "$src/.claude-plugin" … "$src/scripts" …` byte-copies
# the vendored helper tree (asserted above), and install.sh routes each composite
# action through `install_managed`, whose directory arm copies with a plain
# mode-preserving `cp -R`. That copy now lands on a `.prflow-stage` sibling which is
# then `mv`d into place (issue #959: an in-place `rm -rf` + `cp -R` leaves a window
# where a mid-copy failure strands a half-written tree, and because the abort happens
# before the manifest write the NEXT run reads those bytes as a local edit and
# preserves the corruption). `mv` is mode-preserving too — it is a rename — so the
# exec-bit guarantee is unchanged; only the destination literal moved. Pin the
# routing, the staged copy invocation, and the swap (not a bare "cp -R" that a doc
# mention could satisfy) plus the absence of `--no-preserve`, rather than a stdlib
# copy demo that would pass regardless of what these files do.
assert_eq("#703 AC20: install.sh copies the composite-action helpers with mode-preserving cp -R",
          True, ('install_managed ".github/actions/$a" "$SRC/.github/actions/$a"' in _install_sh
                 and 'cp -R "$srcp" "$rel.prflow-stage"' in _install_sh
                 and 'mv "$rel.prflow-stage" "$rel"' in _install_sh))
assert_eq("#703 AC20: install.sh never strips modes with --no-preserve",
          False, "--no-preserve" in _install_sh)
assert_eq("#703 AC20: the vendor slice never strips modes with --no-preserve",
          False, "--no-preserve" in _vendor_slice)

# (c) Consumer-owned content. All three flows delegate config + prompt-extension
# provisioning to the SAME shared scaffolder (scripts/scaffold-config.sh), so they
# cannot drift; that scaffolder preserves an existing config.json (backfill-only,
# adding only newly-introduced keys, never deleting) and backfills prompt-extension
# examples per file only when absent, never clobbering a live extension.
assert_eq("#703 AC20: install.sh delegates config/prompt-extension provisioning to scaffold-config.sh",
          True, "scaffold-config.sh" in _install_sh)
assert_eq("#703 AC20: /devflow:init delegates to the same shared scaffold-config.sh",
          True, "scaffold-config.sh" in _init_skill)
# Pin the CODE constructs that implement the no-clobber contract, not the prose
# that describes it (a comment pin goes green even if the logic is inverted):
#  * config preserved when present — the `[ -f "$CONFIG" ]` guard;
#  * additive backfill — the jq deep-merge `$ex[0] * $cfg[0]` (config on the right
#    wins, so user values are kept and only example-introduced keys are added);
#  * prompt-extension no-clobber — the per-file `[ -e "$pe_target" ] || [ -e
#    "$pe_live" ]` skip guard (never overwrites an adopter's example or live ext).
assert_eq("#703 AC20: scaffold-config.sh preserves an existing config.json (no clobber)",
          True, 'if [ -f "$CONFIG" ]; then' in _scaffold_sh)
assert_eq("#703 AC20: scaffold-config.sh backfills additively via the example*config deep-merge",
          True, "$ex[0] * $cfg[0]" in _scaffold_sh)
assert_eq("#703 AC20: scaffold-config.sh skips (never clobbers) an existing prompt extension",
          True, '[ -e "$pe_target" ] || [ -e "$pe_live" ]' in _scaffold_sh)


# ── issue #555: scripts/discover-deferral-manifests.py — fail-closed Phase 4.0.5
# ── deferrals-manifest discovery. The retired inline `find $SEARCH_DIRS … | sort`
# ── collapsed a FAILED search and a CLEAN no-match search onto the same empty
# ── output, so a degraded search read as the clean no-op and stranded deferrals.
# ── These fixtures drive the helper's CLI contract at module level (main(argv)
# ── returns the exit code and writes to sys.stdout/stderr, so no subprocess is
# ── needed) — the automated boundary the extraction exists to create, since a
# ── markdown fence cannot be executed by the suite.
print("discover-deferral-manifests.py (#555): per-root classification + exit contract")


def _dm_run(argv, cwd=None):
    """Run the helper's main() with argv, returning (rc, stdout, stderr).

    `cwd` is an operand for the #1374 presence mode only: it composes its search
    directories from the cwd-relative literal `.prflow/tmp/review`, exactly as the
    §4.0.5 filing fence does, so driving it from anywhere else would search a tree the
    fixture never built and collapse every state onto `absent`. Discovery mode takes
    absolute roots and passes no `cwd`.
    """
    out, err = io.StringIO(), io.StringIO()
    _prev = os.getcwd()
    if cwd is not None:
        os.chdir(cwd)
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            rc = discover_deferrals.main(list(argv))
    finally:
        if cwd is not None:
            os.chdir(_prev)
    return rc, out.getvalue(), err.getvalue()


def _dm_manifest(root, run_id, content='{"deferrals": []}'):
    """Create <root>/<run_id>/deferrals.json with the given content and return
    its POSIX-form path (the shape the helper prints)."""
    d = Path(root) / run_id
    d.mkdir(parents=True, exist_ok=True)
    p = d / 'deferrals.json'
    p.write_text(content, encoding='utf-8')
    return p.as_posix()


with tempfile.TemporaryDirectory() as _dm_base:
    _base = Path(_dm_base)
    # A populated slug root with TWO distinct run-id manifests (the #68 F1 shape:
    # a first review-and-fix run plus its bounded re-review write two manifests
    # under one slug dir — the primary production multiplicity).
    _pop = _base / 'pr-500'
    _m1 = _dm_manifest(_pop, 'run-aaa', '{"deferrals": [{"file": "a.py"}]}')
    _m2 = _dm_manifest(_pop, 'run-bbb', '{"deferrals": [{"file": "b.py"}]}')
    _absent = str(_base / 'pr-nonexistent-slug')
    # A regular file supplied as a root → the deterministic ENOTDIR traversal
    # failure (a chmod-000 fixture would pass vacuously under a root-privileged runner).
    _regfile = _base / 'not-a-dir'
    _regfile.write_text('x', encoding='utf-8')

    # #533 regression: one absent root + one populated root → both paths printed, exit 0.
    _rc, _so, _se = _dm_run([_absent, str(_pop)])
    assert_eq("#555 #533-regression: absent + populated → exit 0", 0, _rc)
    assert_eq("#555 #533-regression: the populated root's manifests are printed",
              sorted([_m1, _m2]), sorted(_so.split()))

    # Masking regression: one failed root + one populated root → found path printed
    # AND exit 3. Output production/sorting cannot alter the exit status (the
    # property whose absence let #533's degraded search print as a clean no-op).
    _rc, _so, _se = _dm_run([str(_regfile), str(_pop)])
    assert_eq("#555 masking-regression: failed + populated → exit 3 (partial)", 3, _rc)
    assert_eq("#555 masking-regression: the found manifests are STILL printed",
              sorted([_m1, _m2]), sorted(_so.split()))
    assert_eq("#555 masking-regression: partial marker present", True,
              'devflow: discovery partial:' in _se)
    assert_eq("#555 masking-regression: failed marker ABSENT (markers mutually exclusive)",
              False, 'devflow: discovery failed:' in _se)

    # Root-level traversal failure: a single regular-file root → exit 4, failed
    # marker present, partial marker absent.
    _rc, _so, _se = _dm_run([str(_regfile)])
    assert_eq("#555 ENOTDIR root: single regular-file root → exit 4", 4, _rc)
    assert_eq("#555 ENOTDIR root: failed marker present", True,
              'devflow: discovery failed:' in _se)
    assert_eq("#555 ENOTDIR root: partial marker ABSENT (exclusivity)", False,
              'devflow: discovery partial:' in _se)
    # Target the PER-ROOT line specifically: the aggregate marker line also contains
    # 'failed traversal', so a bare substring test would pass even with no per-root
    # breadcrumb at all (it did — the non-directory arm emitted none until #555 review).
    assert_eq("#555 ENOTDIR root: per-root breadcrumb names the failed root", True,
              any(ln.startswith('devflow: discovery: root ')
                  and str(_regfile) in ln and 'failed traversal' in ln
                  for ln in _se.splitlines()))

    # Every root failed (two regular files) → exit 4 with the same marker assertions.
    _rc, _so, _se = _dm_run([str(_regfile), str(_regfile)])
    assert_eq("#555 all-failed: two regular-file roots → exit 4", 4, _rc)
    assert_eq("#555 all-failed: failed marker present", True,
              'devflow: discovery failed:' in _se)
    assert_eq("#555 all-failed: partial marker ABSENT", False,
              'devflow: discovery partial:' in _se)

    # All roots absent → exit 0, empty stdout.
    _rc, _so, _se = _dm_run([_absent, str(_base / 'pr-also-absent')])
    assert_eq("#555 all-absent: exit 0", 0, _rc)
    assert_eq("#555 all-absent: empty stdout", "", _so)
    assert_eq("#555 all-absent: roots-echo classifies both absent", 2,
              _se.count('=absent'))

    # Zero arguments → exit 2 with a usage message, NO discovery-failed marker.
    _rc, _so, _se = _dm_run([])
    assert_eq("#555 zero-args: exit 2", 2, _rc)
    assert_eq("#555 zero-args: failed marker ABSENT (a usage message, not a failure)",
              False, 'devflow: discovery failed:' in _se)
    assert_eq("#555 zero-args: usage breadcrumb emitted", True, 'usage:' in _se)

    # A 0-byte deferrals.json is excluded (mirrors find -size +0c).
    _z = _base / 'zbyte'
    (_z / 'run-z').mkdir(parents=True)
    (_z / 'run-z' / 'deferrals.json').write_text('', encoding='utf-8')
    _rc, _so, _se = _dm_run([str(_z)])
    assert_eq("#555 0-byte manifest excluded → exit 0, empty stdout", (0, ""), (_rc, _so))

    # Wrong-depth manifests excluded: one at depth 1 (directly in root) and one at
    # depth 3 (root/a/b/deferrals.json) — only depth-2 matches.
    _wd = _base / 'wrongdepth'
    (_wd / 'a' / 'b').mkdir(parents=True)
    (_wd / 'deferrals.json').write_text('d1', encoding='utf-8')
    (_wd / 'a' / 'b' / 'deferrals.json').write_text('d3', encoding='utf-8')
    _rc, _so, _se = _dm_run([str(_wd)])
    assert_eq("#555 wrong-depth (depth-1 and depth-3) excluded → empty stdout",
              (0, ""), (_rc, _so))

    # Identical duplicate roots → de-duplicated output.
    _rc, _so, _se = _dm_run([str(_pop), str(_pop)])
    assert_eq("#555 duplicate roots → de-duplicated, sorted output",
              sorted([_m1, _m2]), _so.split())

    # Two populated roots → all paths printed, sorted (multiplicity across roots).
    _pop2 = _base / 'branch-slug'
    _m3 = _dm_manifest(_pop2, 'run-ccc', '{"deferrals": [{"file": "c.py"}]}')
    _rc, _so, _se = _dm_run([str(_pop), str(_pop2)])
    assert_eq("#555 two populated roots → all manifests printed, sorted",
              sorted([_m1, _m2, _m3]), _so.split())

    # Roots-echo on a mixed run names both absolute resolved paths with classifications.
    _rc, _so, _se = _dm_run([_absent, str(_pop)])
    assert_eq("#555 roots-echo: line present naming absolute paths + classifications",
              True, 'devflow: discovery roots:' in _se
              and os.path.abspath(_absent) + '=absent' in _se
              and os.path.abspath(str(_pop)) + '=ok' in _se)

    # POSIX-form output: no backslash appears in emitted paths (#275 host shape).
    # NOTE this assertion alone is structurally vacuous wherever os.sep == '/': the
    # `.replace(os.sep, "/")` is an identity there, so deleting it keeps this green.
    # The non-vacuous half is below — drive the separator the contract exists for.
    _rc, _so, _se = _dm_run([str(_pop)])
    assert_eq("#555 POSIX-form: no backslash in emitted paths", False, '\\' in _so)

    # Non-vacuous POSIX-form pin: drive the extracted `_posix` normalizer directly with
    # os.sep set to the native-Windows separator the contract exists for (#275). Going
    # through classify_root cannot work — on a POSIX host os.path.join still joins with
    # '/', so `.replace(os.sep, "/")` stays an identity and the assertion passes for the
    # wrong reason; that vacuity was caught by mutation, which is why the normalizer is
    # a callable rather than an inline expression.
    _saved_sep = discover_deferrals.os.sep
    try:
        discover_deferrals.os.sep = '\\'
        assert_eq("#555 POSIX-form (non-vacuous): _posix rewrites a backslash-separated path to POSIX form",
                  'root/run-1/deferrals.json',
                  discover_deferrals._posix('root\\run-1\\deferrals.json'))
    finally:
        discover_deferrals.os.sep = _saved_sep

    # Roots-echo abspath: every fixture root above is ALREADY absolute, so
    # os.path.abspath is an identity there and the assertion passes for the wrong
    # reason. Drive a RELATIVE root from inside _base so abspath has real work.
    _saved_cwd = os.getcwd()
    try:
        os.chdir(str(_base))
        _rc, _so, _se = _dm_run(['pr-500'])
        assert_eq("#555 roots-echo (non-vacuous): a RELATIVE root is echoed as its absolute path",
                  (True, False),
                  (os.path.join(str(_base), 'pr-500') + '=ok' in _se,
                   'devflow: discovery roots: pr-500=' in _se))
    finally:
        os.chdir(_saved_cwd)

    # A root argument containing a space is handled at the helper's own boundary
    # (the fence never produces one, but the contract must not crash on one).
    _spaced = _base / 'a b slug'
    _ms = _dm_manifest(_spaced, 'run-sp', '{"deferrals": [{"file": "s.py"}]}')
    _rc, _so, _se = _dm_run([str(_spaced)])
    assert_eq("#555 spaced root: classified ok, its manifest printed",
              (0, [_ms]), (_rc, _so.splitlines()))

# A MID-TRAVERSAL OSError (raised INSIDE an otherwise-populated root, not at the
# root itself) must classify that root `failed` — the helper must NOT rely on
# os.walk's default error-swallowing. Monkeypatch os.walk at module level (the
# importlib _load pattern makes this deterministic and immune to the
# root-privilege hazard a chmod fixture carries).
with tempfile.TemporaryDirectory() as _dm_mt:
    _dm_manifest(_dm_mt, 'run-x', '{"deferrals": [{"file": "x.py"}]}')
    _saved_walk = discover_deferrals.os.walk

    # Drive the onerror CALLBACK rather than raising directly. A stub that raises
    # unconditionally exercises the `except OSError` handler but never the onerror
    # channel — so it stays GREEN when `onerror=_raise` is dropped, which is the
    # exact regression (os.walk's default silently skips an unreadable subtree and
    # classifies the root `ok`) the argument exists to prevent. Calling onerror
    # makes the assertion fail closed: with `onerror=None` the callback is absent
    # and no OSError ever reaches classify_root.
    def _boom_walk(path, onerror=None):
        exc = OSError(5, "simulated mid-traversal I/O error")
        if onerror is not None:
            onerror(exc)
        return iter(())

    try:
        discover_deferrals.os.walk = _boom_walk
        _status, _matches = discover_deferrals.classify_root(_dm_mt)
        assert_eq("#555 mid-traversal OSError inside a populated root → classified 'failed'",
                  ('failed', []), (_status, _matches))
    finally:
        discover_deferrals.os.walk = _saved_walk
    _status2, _ = discover_deferrals.classify_root(_dm_mt)
    assert_eq("#555 mid-traversal: after restore the same root classifies 'ok'",
              'ok', _status2)

# The §4.0.5 fence classifies partial-vs-failed from the aggregate marker, and the PER-ROOT
# breadcrumb is emitted on BOTH paths: a reword letting it carry either marker substring would
# classify an all-failed run as partial, which files from a stale aggregate instead of refusing.
with tempfile.TemporaryDirectory() as _dm_excl:
    _dm_notdir = os.path.join(_dm_excl, 'regular-file-root')
    with open(_dm_notdir, 'w', encoding='utf-8') as _fh:
        _fh.write('not a directory\n')
    _, _, _dm_excl_err = _dm_run([_dm_notdir])
    _dm_perroot = [ln for ln in _dm_excl_err.splitlines()
                   if ln.startswith('devflow: discovery: root ')]
    assert_eq("#555 marker-exclusivity: the per-root failure breadcrumb is emitted",
              1, len(_dm_perroot))
    assert_eq("#555 marker-exclusivity: the per-root breadcrumb carries NEITHER aggregate marker",
              (False, False),
              (discover_deferrals.MARKER_PARTIAL in _dm_perroot[0],
               discover_deferrals.MARKER_FAILED in _dm_perroot[0]))

# The fixture above reaches only the NON-DIRECTORY arm. Pin the OSError arm too: it is a second,
# independently-worded breadcrumb interpolating the OSError text, so a reword carrying a marker
# substring would misclassify an all-failed run while the fixture above stayed green.
with tempfile.TemporaryDirectory() as _dm_excl2:
    _dm_manifest(_dm_excl2, 'run-y', '{"deferrals": [{"file": "y.py"}]}')
    _saved_walk2 = discover_deferrals.os.walk

    def _boom_walk2(path, onerror=None):
        exc = OSError(5, "simulated mid-traversal I/O error")
        if onerror is not None:
            onerror(exc)
        return iter(())

    _err2 = io.StringIO()
    try:
        discover_deferrals.os.walk = _boom_walk2
        with contextlib.redirect_stderr(_err2):
            discover_deferrals.classify_root(_dm_excl2)
    finally:
        discover_deferrals.os.walk = _saved_walk2
    _dm_perroot2 = [ln for ln in _err2.getvalue().splitlines()
                    if ln.startswith('devflow: discovery: root ')]
    assert_eq("#555 marker-exclusivity (OSError arm): the per-root breadcrumb is emitted",
              1, len(_dm_perroot2))
    assert_eq("#555 marker-exclusivity (OSError arm): the per-root breadcrumb carries NEITHER aggregate marker",
              (False, False),
              (discover_deferrals.MARKER_PARTIAL in _dm_perroot2[0],
               discover_deferrals.MARKER_FAILED in _dm_perroot2[0]))

# The `os.path.getsize` OSError arm (a manifest vanishing between the os.walk yield and
# the size probe) is a THIRD way into the `except OSError` handler, and the two fixtures
# above cannot reach it: both stub os.walk to `return iter(())`, so the loop body — and
# the getsize call inside it — never executes. Without this fixture the source comment
# "getsize can itself raise OSError … handled by the except" is asserted by construction
# only, and hoisting the probe outside the try (or guarding it with a bare `except:
# pass`) would silently turn a vanished manifest into a CLEAN `ok` with the manifest
# missing — the exact silent-loss shape #555 exists to remove, one level down.
# Positive control first: the same fixture classifies `ok` and yields the manifest, so a
# `failed` below can only come from the getsize probe and not from an earlier guard.
with tempfile.TemporaryDirectory() as _dm_gs:
    _gs_manifest = _dm_manifest(_dm_gs, 'run-gs', '{"deferrals": [{"file": "g.py"}]}')
    assert_eq("#555 getsize arm (positive control): the un-patched fixture classifies 'ok' with its manifest",
              ('ok', [_gs_manifest]), discover_deferrals.classify_root(_dm_gs))

    _saved_getsize = discover_deferrals.os.path.getsize

    def _boom_getsize(path):
        raise OSError(2, "simulated vanished manifest")

    _gs_err = io.StringIO()
    try:
        discover_deferrals.os.path.getsize = _boom_getsize
        with contextlib.redirect_stderr(_gs_err):
            _gs_status, _gs_matches = discover_deferrals.classify_root(_dm_gs)
    finally:
        discover_deferrals.os.path.getsize = _saved_getsize
    assert_eq("#555 getsize OSError mid-walk → the root classifies 'failed', matches dropped",
              ('failed', []), (_gs_status, _gs_matches))
    # Attribute the rejection: it must be the OSError per-root breadcrumb naming this
    # root, not some other failure path, and it must carry neither aggregate marker.
    _gs_perroot = [ln for ln in _gs_err.getvalue().splitlines()
                   if ln.startswith('devflow: discovery: root ')]
    assert_eq("#555 getsize OSError arm: attributed by the OSError per-root breadcrumb naming this root",
              (1, True, True, False, False),
              (len(_gs_perroot),
               os.path.abspath(_dm_gs) in _gs_perroot[0] if _gs_perroot else False,
               'simulated vanished manifest' in _gs_perroot[0] if _gs_perroot else False,
               discover_deferrals.MARKER_PARTIAL in _gs_perroot[0] if _gs_perroot else True,
               discover_deferrals.MARKER_FAILED in _gs_perroot[0] if _gs_perroot else True))

# The "regular files only" narrowing is the ONE claimed behavioral difference from the
# retired `find -mindepth 2 -maxdepth 2 -name deferrals.json -size +0c` (which had no
# `-type f` and would have matched a DIRECTORY named deferrals.json). It rests entirely
# on os.walk splitting its yield into dirnames/filenames and the membership test reading
# `filenames` — a rewrite reading `dirnames + filenames` would re-admit the directory and
# hand file-deferrals.py a path it cannot read, with nothing to catch it. Positive control
# on the same root: a sibling REGULAR manifest at the same depth IS matched, so a
# directory's absence from the output cannot be an artifact of the root matching nothing.
with tempfile.TemporaryDirectory() as _dm_dirname:
    (Path(_dm_dirname) / 'run-dir' / 'deferrals.json').mkdir(parents=True)
    _dn_sibling = _dm_manifest(_dm_dirname, 'run-file', '{"deferrals": [{"file": "f.py"}]}')
    _dn_status, _dn_matches = discover_deferrals.classify_root(_dm_dirname)
    assert_eq("#555 regular files only: a DIRECTORY named deferrals.json at depth 2 never matches, while its regular sibling does",
              ('ok', [_dn_sibling]), (_dn_status, _dn_matches))

# Symlink roots. The docstring claims the roots-echo path is `os.path.abspath` —
# "normalized, NOT symlink-resolved" — and nothing pinned it, so a swap to
# os.path.realpath would silently start echoing a path the operator never supplied,
# breaking the documented cwd-drift heuristic (which compares the echoed paths against
# where Phase 3.3 executed). Two arms: a symlink TO a populated dir searches through the
# link and echoes the LINK path, and a DANGLING symlink takes os.path.exists's
# follow-the-link False and classifies `absent` (benign) rather than `failed`.
with tempfile.TemporaryDirectory() as _dm_sym:
    _sym_real = Path(_dm_sym) / 'real-slug'
    _sym_manifest = _dm_manifest(_sym_real, 'run-sym', '{"deferrals": [{"file": "s.py"}]}')
    _sym_link = Path(_dm_sym) / 'link-slug'
    _sym_dangling = Path(_dm_sym) / 'dangling-slug'
    try:
        _sym_link.symlink_to(_sym_real, target_is_directory=True)
        _sym_dangling.symlink_to(Path(_dm_sym) / 'no-such-target', target_is_directory=True)
        _sym_supported = True
    except (OSError, NotImplementedError):
        # A host without symlink privilege (native Windows without developer mode).
        # Recorded rather than silently skipped; CI runs on Linux where it is supported.
        _sym_supported = False
        print("  #555 symlink-root fixture unavailable: this host cannot create symlinks")
    if _sym_supported:
        # The emitted match is rendered under the LINK path, not the resolved target —
        # os.walk descends the link without rewriting the prefix, and the helper joins
        # onto the supplied root. That is the stronger form of the "NOT symlink-resolved"
        # contract: a swap to realpath anywhere in this path would change the emitted
        # manifest paths themselves, not merely the echo, and file-deferrals.py would be
        # handed a path the run never named.
        assert_eq("#555 symlink root: a symlink to a populated dir is searched through the link, and matches are emitted under the LINK path (not the resolved target)",
                  ('ok', [(_sym_link / 'run-sym' / 'deferrals.json').as_posix()], True),
                  discover_deferrals.classify_root(str(_sym_link))
                  + (_sym_manifest == (_sym_real / 'run-sym' / 'deferrals.json').as_posix(),))
        _rc, _so, _se = _dm_run([str(_sym_link)])
        assert_eq("#555 symlink root: the roots-echo carries the LINK path (abspath, NOT symlink-resolved)",
                  (True, False),
                  (os.path.abspath(str(_sym_link)) + '=ok' in _se,
                   os.path.abspath(str(_sym_real)) + '=ok' in _se))
        assert_eq("#555 dangling symlink root: classified 'absent' (benign), never 'failed'",
                  ('absent', []),
                  discover_deferrals.classify_root(str(_sym_dangling)))


# ── issue #1374: the PRESENCE mode. Phase 4.0.5's filing procedure moved behind a
# ── predicate-gated reference, and this mode IS that predicate: it answers whether
# ── any deferred review finding is present for a PR without the phase file having to
# ── carry the filing procedure's bytes. Its contract is deliberately flat where the
# ── discovery mode's is not — present/absent/unestablished as exit 0/1/2 — so both
# ── gated Phase 4 sub-steps document one three-state shape. The exit status carries
# ── every state; the shipped stub additionally requires the literal `absent: 0` line
# ── on its skip arm, because a crashing interpreter also exits 1.
print("discover-deferral-manifests.py (#1374): presence mode — three-state exit contract")

_PM_FLAG = '--presence-for-pr'


def _pm_fence_tr_chain():
    """Extract the §4.0.5 fence's OWN `tr` chain from the shipped reference file.

    Reading the chain out of the artifact is what makes this a differential rather than a
    third copy: a hand-typed chain in this file would keep agreeing with the port after
    someone widened the fence's keep-set, and the drift the AC exists to catch would ship
    green. Returns the pipeline text after `printf '%s' "$CUR_BRANCH" | `, or None when the
    line cannot be located — which the caller records as a degradation, never as agreement.
    """
    ref = cwc.REPO_ROOT / 'skills/implement/references/deferred-review-findings.md'
    try:
        text = ref.read_text(encoding='utf-8')
    except OSError:
        return None
    marker = 'BRANCH_SLUG=$(printf \'%s\' "$CUR_BRANCH" | '
    for line in text.splitlines():
        if marker in line:
            chain = line.split(marker, 1)[1]
            return chain[:-1] if chain.endswith(')') else None
    return None


def _pm_tr_slugs(names, chain):
    """Derive each branch slug through the fence's own extracted `tr` chain.

    `LC_ALL=C` pins it to byte semantics, which is what makes the comparison deterministic
    across a BSD `tr` and a GNU one; the port is likewise byte-oriented ASCII. The whole
    table runs in ONE shell, emitting one NUL-terminated slug per input, so the
    differential costs a single spawn rather than one per row. Returns None when the chain
    could not be run or the output is not attributable, so the differential records a
    degradation instead of asserting against an empty pipeline (the guard-class-2 shape: a
    missing tool must never read as a clean agreement).
    """
    _env = dict(os.environ, LC_ALL='C')
    script = ('for a in "$@"; do printf \'%s\' "$a" | ' + chain
              + "; printf '\\000'; done")
    try:
        _p = _subprocess.run(['sh', '-c', script, 'sh'] + list(names),
                             capture_output=True, text=True, env=_env)
    except OSError:
        return None
    if _p.returncode != 0:
        return None
    slugs = _p.stdout.split('\x00')[:-1]
    return slugs if len(slugs) == len(names) else None


with tempfile.TemporaryDirectory() as _pm_base:
    _pmb = Path(_pm_base)

    # ---- AC6: the differential slug table. Each row is a branch-name shape the
    # ---- criterion names; each asserts the in-Python derivation equals the live
    # ---- `tr` chain's output for that same input.
    _PM_BRANCH_INPUTS = (
        'Feature-Branch',                 # mixed case
        'feat/issue-1374',                # a path separator
        'issue#1374 (draft)!',            # characters outside [a-z0-9._-]
        '###!!!',                         # every character dropped by the filter
        '\u212aELVIN',                     # U+212A KELVIN SIGN: str.lower() maps it INTO
                                          # the keep-set ('k'), the fence's tr in the C
                                          # locale drops it — the one row that catches a
                                          # port rewritten to use str.lower()
        '',                               # empty name (detached HEAD)
        'worktree-issue-1374',            # the ordinary shape, as a control
    )
    _pm_chain = _pm_fence_tr_chain()
    assert_eq("#1374 AC6: the fence's tr chain is locatable in the shipped reference "
              "(the differential reads the artifact, not a copy of it)",
              True, _pm_chain is not None)
    _pm_expected = _pm_tr_slugs(_PM_BRANCH_INPUTS, _pm_chain) if _pm_chain else None
    if _pm_expected is None:
        # Recorded rather than silently passing: without a runnable `tr` the
        # expectation side of the differential cannot be produced, and asserting
        # against an empty pipeline would agree for the wrong reason.
        print("  #1374 AC6 differential unavailable: this host cannot run the fence's `tr` chain")
    else:
        for _bn, _want in zip(_PM_BRANCH_INPUTS, _pm_expected):
            assert_eq(f"#1374 AC6: in-Python slug matches the fence's live tr chain for {_bn!r}",
                      _want, discover_deferrals._derive_branch_slug(_bn))

    # ---- The escape guard. The filter keeps `.` and `-`, so a branch named `..`
    # ---- slugs to `..` and would resolve the branch candidate OUTSIDE the review
    # ---- root. Driven directly, because git refuses to create such a branch.
    assert_eq("#1374: a slug that would escape the review root is rejected",
              (True, False),
              (discover_deferrals._slug_escapes_review_root('.prflow/tmp/review', '..'),
               discover_deferrals._slug_escapes_review_root('.prflow/tmp/review', 'pr-9')))

    def _pm_tree(name, branch='fixture-branch'):
        """Build a fixture working directory as a git repo checked out on `branch`.

        ALWAYS a repository, because that is the production shape: the predicate runs from
        a checkout, so a directory with no repository above it is an anomaly the mode now
        reports as unestablished rather than a benign stand-in for a detached HEAD. The
        detached-HEAD case (git answering cleanly with no branch) is driven by substituting
        the resolver instead. Returns (path, review_root_path).
        """
        d = _pmb / name
        (d / '.prflow' / 'tmp' / 'review').mkdir(parents=True, exist_ok=True)
        _gi = _subprocess.run(['git', 'init', '-q', '-b', branch, str(d)],
                              capture_output=True, text=True)
        if _gi.returncode != 0:
            # A failed init leaves a non-repo cwd, which the hardened resolver reports as
            # branch-unresolvable — so every fixture below would fail on the unestablished
            # arm instead. Raise here so the failure is attributed to `git init`.
            raise AssertionError(
                f'#1374 harness: git init -b {branch!r} failed (rc={_gi.returncode}); '
                f'the presence-mode fixtures cannot be built: {_gi.stderr}')
        return d, d / '.prflow' / 'tmp' / 'review'

    # ---- Happy path 1: one non-empty run-scoped manifest under the PR slug.
    _d, _rev = _pm_tree('present-pr-slug')
    _dm_manifest(_rev / 'pr-77', 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _rc, _so, _se = _dm_run([_PM_FLAG, '77'], _d)
    assert_eq("#1374 AC4: a non-empty run-scoped manifest under the PR slug reports present (exit 0)",
              (0, True), (_rc, _so.startswith('present:')))

    # ---- Happy path 2: the manifest lives ONLY under the branch slug — the shape a
    # ---- branch-mode /prflow:review-and-fix run writes. Deliberately no manifest under
    # ---- the PR slug: with one there, the assertion would pass even if the branch-slug
    # ---- candidate were dropped entirely, and could never fail for the property it names.
    _d, _rev = _pm_tree('present-branch-slug', branch='feat/Branch-Slug')
    _dm_manifest(_rev / 'feat-branch-slug', 'run-b', '{"deferrals": [{"file": "b.py"}]}')
    _rc, _so, _se = _dm_run([_PM_FLAG, '78'], _d)
    assert_eq("#1374: a manifest under the branch slug alone reports present (the PR slug holds none)",
              (0, True), (_rc, _so.startswith('present:')))

    # ---- Happy path 3: manifests under BOTH candidates, and TWO under one of them. The
    # ---- asymmetry is what discriminates: with one manifest each, `present += 1` and the
    # ---- shipped `present += len(matches)` both yield 2 and the assertion cannot tell
    # ---- them apart. At 2-and-1 the shipped code yields 3 and `present += 1` yields 2,
    # ---- so this also catches `present = len(matches)` and a `break` after the first root.
    _d, _rev = _pm_tree('present-both-slugs', branch='feat/Both-Slugs')
    _dm_manifest(_rev / 'pr-93', 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _dm_manifest(_rev / 'pr-93', 'run-b', '{"deferrals": [{"file": "b.py"}]}')
    _dm_manifest(_rev / 'feat-both-slugs', 'run-c', '{"deferrals": [{"file": "c.py"}]}')
    _rc, _so, _se = _dm_run([_PM_FLAG, '93'], _d)
    assert_eq("#1374: matches from both candidates are SUMMED into the reported count",
              (0, 'present: 3'), (_rc, _so.strip()))

    # ---- AC4's second half: ONLY a non-empty slug-level aggregate, no run-scoped
    # ---- manifest. A predicate reading only the run-scoped source fails open here,
    # ---- because a re-entry after filing has consumed those manifests already.
    _d, _rev = _pm_tree('present-aggregate-only')
    (_rev / 'pr-79').mkdir(parents=True, exist_ok=True)
    (_rev / 'pr-79' / 'deferrals.json').write_text(
        '{"deferrals": [{"file": "a.py"}]}', encoding='utf-8')
    _rc, _so, _se = _dm_run([_PM_FLAG, '79'], _d)
    assert_eq("#1374 AC4: a non-empty slug-level aggregate alone reports present (exit 0)",
              (0, True), (_rc, _so.startswith('present:')))

    # ---- Absent: an empty tree.
    _d, _rev = _pm_tree('absent-empty')
    _rc, _so, _se = _dm_run([_PM_FLAG, '80'], _d)
    assert_eq("#1374 AC5: an empty tree reports absent (exit 1)",
              (1, True), (_rc, _so.startswith('absent:')))

    # ---- Absent: a ZERO-BYTE run-scoped manifest and a zero-byte aggregate. The
    # ---- discovery mode matches only files of non-zero size, and the aggregate check
    # ---- mirrors that rule rather than inventing a second one.
    _d, _rev = _pm_tree('absent-zero-byte')
    _dm_manifest(_rev / 'pr-81', 'run-a', '')
    (_rev / 'pr-81' / 'deferrals.json').write_text('', encoding='utf-8')
    _rc, _so, _se = _dm_run([_PM_FLAG, '81'], _d)
    assert_eq("#1374: a zero-byte manifest and a zero-byte aggregate report absent (exit 1)",
              (1, True), (_rc, _so.startswith('absent:')))

    # ---- Absent: a manifest nested one level too deep. The depth-2 matching rule is
    # ---- the discovery mode's, reused rather than re-derived.
    _d, _rev = _pm_tree('absent-too-deep')
    _deep = _rev / 'pr-82' / 'run-a' / 'extra'
    _deep.mkdir(parents=True, exist_ok=True)
    (_deep / 'deferrals.json').write_text('{"deferrals": [{}]}', encoding='utf-8')
    _rc, _so, _se = _dm_run([_PM_FLAG, '82'], _d)
    assert_eq("#1374: a manifest one level too deep reports absent (exit 1)",
              (1, True), (_rc, _so.startswith('absent:')))

    # ---- Unestablished: an unreadable candidate directory. A regular file standing
    # ---- where the slug directory belongs is the deterministic ENOTDIR shape (a
    # ---- chmod-000 fixture passes vacuously under a root-privileged runner).
    _d, _rev = _pm_tree('unestablished-dir')
    (_rev / 'pr-83').write_text('x', encoding='utf-8')
    _rc, _so, _se = _dm_run([_PM_FLAG, '83'], _d)
    assert_eq("#1374 AC5: an unreadable candidate directory reports unestablished (exit 2) naming that reason, never absent",
              (2, True, True),
              (_rc, 'unestablished: reason=unreadable-directory' in _so, 'root: ' in _so))
    # Attribution, not merely exit code: the aggregate path under a non-directory slug dir
    # also fails to stat, so a naive aggregate probe would name the wrong operand in the
    # reason token the stub quotes into its reflection.
    assert_eq("#1374: that stop is attributed to the directory, not to the aggregate beneath it",
              False, 'unreadable-aggregate' in _so)

    # ---- Unestablished: the aggregate exists but cannot be read as a file.
    _d, _rev = _pm_tree('unestablished-aggregate')
    (_rev / 'pr-84' / 'deferrals.json').mkdir(parents=True, exist_ok=True)
    _rc, _so, _se = _dm_run([_PM_FLAG, '84'], _d)
    assert_eq("#1374: an aggregate present but unreadable reports unestablished (exit 2) naming that reason",
              (2, True), (_rc, 'unestablished: reason=unreadable-aggregate' in _so))

    # ---- Present WINS over an unreadable sibling. The PR slug is a regular file (the
    # ---- same deterministic ENOTDIR shape as above) while the branch slug holds a real
    # ---- manifest: a finding the mode positively saw is not made less present by a
    # ---- directory it could not read. Without the `if present:` check ordered ahead of
    # ---- the failed-sibling checks this returns unestablished, and no other fixture
    # ---- pairs a non-zero count with a failed root, so a reordering regression here
    # ---- would keep every one of them green.
    _d, _rev = _pm_tree('present-over-failed-sibling', branch='feat/Wins')
    (_rev / 'pr-85').write_text('x', encoding='utf-8')
    _dm_manifest(_rev / 'feat-wins', 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _rc, _so, _se = _dm_run([_PM_FLAG, '85'], _d)
    assert_eq("#1374: a present branch-slug manifest wins over an unreadable PR-slug sibling (exit 0)",
              (0, 'present: 1'), (_rc, _so.strip()))
    # Control on the SAME fixture shape: drop the manifest and the sibling's unreadability
    # is what decides. Without it, a fixture whose PR slug was in fact readable would give
    # the assertion above the identical green while exercising no such precedence.
    _d, _rev = _pm_tree('present-over-failed-sibling-control', branch='feat/Wins')
    (_rev / 'pr-85').write_text('x', encoding='utf-8')
    _rc, _so, _se = _dm_run([_PM_FLAG, '85'], _d)
    assert_eq("#1374: the same fixture WITHOUT the manifest reports unestablished — the sibling is genuinely unreadable",
              (2, True), (_rc, 'unestablished: reason=unreadable-directory' in _so))

    # ---- Unestablished: a malformed invocation. Mirrors workpad.py deferred-presence,
    # ---- whose usage exit is deliberately its unestablished code so a bad call routes
    # ---- fail-closed into reading the reference rather than silently skipping it.
    _d, _rev = _pm_tree('unestablished-usage')
    for _bad in ([_PM_FLAG], [_PM_FLAG, ''], [_PM_FLAG, 'abc'], [_PM_FLAG, '1', '2']):
        _rc, _so, _se = _dm_run(_bad, _d)
        assert_eq(f"#1374 AC5: malformed invocation {_bad!r} reports unestablished (exit 2) naming that reason",
                  (2, True), (_rc, 'unestablished: reason=malformed-invocation' in _so))
    # `str.isdigit()` is Unicode-aware, so a non-ASCII digit would otherwise compose a
    # search directory no producer writes and report `absent` — the one answer this mode
    # must never reach by accident.
    _rc, _so, _se = _dm_run([_PM_FLAG, '\u00b2'], _d)
    assert_eq("#1374: a non-ASCII digit is a malformed invocation, not an absent PR",
              (2, True), (_rc, 'unestablished: reason=malformed-invocation' in _so))

    # ---- AC5's distinctness property, asserted over the codes the fixtures OBSERVED.
    # ---- A `len({0, 1, 2})` form would be a tautology over the test's own constants and
    # ---- would stay green whatever cmd_presence returned.
    _d, _rev = _pm_tree('distinctness')
    _dm_manifest(_rev / 'pr-90', 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _pm_present_rc = _dm_run([_PM_FLAG, '90'], _d)[0]
    _pm_absent_rc = _dm_run([_PM_FLAG, '91'], _d)[0]
    (_rev / 'pr-92').write_text('x', encoding='utf-8')
    _pm_unest_rc = _dm_run([_PM_FLAG, '92'], _d)[0]
    assert_eq("#1374 AC5: present/absent/unestablished occupy three distinct exit codes",
              3, len({_pm_present_rc, _pm_absent_rc, _pm_unest_rc}))

    # ---- A detached HEAD — git answering cleanly with NO branch name — is benign: the PR
    # ---- slug alone is searched and the answer still lands on 0/1, never an error. This
    # ---- is the one empty-branch shape that is not a failure, which is exactly why the
    # ---- mode distinguishes it from the unresolvable case asserted further below.
    _d, _rev = _pm_tree('detached-head')
    _dm_manifest(_rev / 'pr-85', 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _saved_detach = discover_deferrals._resolve_current_branch
    try:
        discover_deferrals._resolve_current_branch = lambda: ''
        _rc, _so, _se = _dm_run([_PM_FLAG, '85'], _d)
    finally:
        discover_deferrals._resolve_current_branch = _saved_detach
    assert_eq("#1374: a detached HEAD searches the PR slug alone and does not error",
              (0, True, 1),
              (_rc, _so.startswith('present:'), _se.count('/review/pr-85=')))

    # ---- De-duplication: when the branch slug IS the PR slug, the directory is
    # ---- classified once. Read off the roots-echo, the mode's own observable.
    _d, _rev = _pm_tree('dedup', branch='pr-86')
    _dm_manifest(_rev / 'pr-86', 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _rc, _so, _se = _dm_run([_PM_FLAG, '86'], _d)
    assert_eq("#1374: a branch slug identical to the PR slug is searched exactly once",
              (0, 1),
              (_rc, _se.count(os.path.abspath(str(_rev / 'pr-86')) + '=')))

    # ---- Idempotency: two consecutive invocations over an unchanged tree agree, and
    # ---- an invocation after the aggregate is hydrated STILL reports present — the
    # ---- property that keeps file-deferrals.py's idempotent re-file path reachable.
    _d, _rev = _pm_tree('idempotent')
    _dm_manifest(_rev / 'pr-87', 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _first = _dm_run([_PM_FLAG, '87'], _d)[0]
    _second = _dm_run([_PM_FLAG, '87'], _d)[0]
    (_rev / 'pr-87' / 'deferrals.json').write_text(
        '{"deferrals": [{"file": "a.py", "follow_up": {"issue": 1}}]}', encoding='utf-8')
    _hydrated = _dm_run([_PM_FLAG, '87'], _d)[0]
    assert_eq("#1374: presence is idempotent, and a hydrated aggregate still reports present",
              (0, 0, 0), (_first, _second, _hydrated))

    # ---- The fail-closed arms this mode's whole premise rests on. Each was a fail-OPEN
    # ---- hole before PR #1379's review: every one of them reported `absent` (exit 1,
    # ---- "skip the procedure") on an input the mode could not actually answer for.

    # A crash must not read as absent. CPython exits 1 on an uncaught exception and 1 IS
    # `absent` here, so without the wrapper a traversal crash strands every acknowledged
    # finding and writes no reflection — the stub records one only on exit 2.
    _d, _rev = _pm_tree('crash-is-unestablished')
    _saved_classify = discover_deferrals.classify_root

    def _boom_classify(_root):
        raise RuntimeError('simulated traversal crash')

    try:
        discover_deferrals.classify_root = _boom_classify
        _rc, _so, _se = _dm_run([_PM_FLAG, '95'], _d)
    finally:
        discover_deferrals.classify_root = _saved_classify
    assert_eq("#1374: an uncaught exception reports unestablished (exit 2), NOT absent (exit 1, which CPython also returns on a crash)",
              (2, True, True),
              (_rc, 'unestablished: reason=internal-error' in _so,
               'simulated traversal crash' in _se))
    # Positive control on the same fixture: unpatched, it answers normally, so the arm
    # above measures the wrapper rather than a broken fixture.
    assert_eq("#1374 positive control: the same fixture answers absent when nothing crashes",
              1, _dm_run([_PM_FLAG, '95'], _d)[0])

    # A branch git could not resolve must not read as a detached HEAD: on a FIRST entry
    # there is no aggregate, so a branch-mode run's manifest lives ONLY under the branch
    # slug and that candidate is the sole evidence.
    _d, _rev = _pm_tree('branch-unresolvable')
    _saved_branch = discover_deferrals._resolve_current_branch
    try:
        discover_deferrals._resolve_current_branch = (
            lambda: discover_deferrals.BRANCH_UNRESOLVABLE)
        _rc, _so, _se = _dm_run([_PM_FLAG, '96'], _d)
    finally:
        discover_deferrals._resolve_current_branch = _saved_branch
    assert_eq("#1374: an unresolvable branch reports unestablished, never absent (the branch slug is the sole source on a first entry)",
              (2, True), (_rc, 'unestablished: reason=branch-unresolvable' in _so))
    assert_eq("#1374 positive control: the same fixture reports absent when the branch resolves",
              1, _dm_run([_PM_FLAG, '96'], _d)[0])

    # The escape guard, driven END-TO-END through cmd_presence. git will not create a `..`
    # branch, so the consuming branch is unreachable without substituting the resolver —
    # and a unit test of the predicate alone cannot catch an inverted or deleted guard.
    _d, _rev = _pm_tree('branch-escapes')
    try:
        discover_deferrals._resolve_current_branch = lambda: '..'
        _rc, _so, _se = _dm_run([_PM_FLAG, '97'], _d)
    finally:
        discover_deferrals._resolve_current_branch = _saved_branch
    assert_eq("#1374: a branch slug that would escape the review root reports unestablished, and the escaping candidate is never searched",
              (2, True, False),
              (_rc, 'unestablished: reason=branch-slug-escapes-review-root' in _so,
               'presence roots:' in _se))

    # A review root that exists but cannot be inspected is NOT the cheap missing-root
    # skip: reading it as missing reintroduces the #555 silent-loss shape one level up.
    _d = _pmb / 'review-root-not-a-dir'
    (_d / '.prflow' / 'tmp').mkdir(parents=True, exist_ok=True)
    (_d / '.prflow' / 'tmp' / 'review').write_text('x', encoding='utf-8')
    _rc, _so, _se = _dm_run([_PM_FLAG, '98'], _d)
    assert_eq("#1374: a review root that exists but is not a directory reports unestablished, never absent",
              (2, True), (_rc, 'unestablished: reason=unreadable-review-root' in _so))

    # The genuinely-missing review root takes the cheap skip and still answers absent —
    # the fast path the predicate exists for, which no other fixture reaches because they
    # all mkdir the root.
    _d = _pmb / 'no-review-root'
    _d.mkdir(parents=True, exist_ok=True)
    _rc, _so, _se = _dm_run([_PM_FLAG, '99'], _d)
    assert_eq("#1374: a missing review root answers absent without deriving the branch",
              (1, 'absent: 0'), (_rc, _so.strip()))

    # The REAL _resolve_current_branch, not a substitute: every assertion above swaps the
    # function out, so nothing else would catch a regression restoring the blanket
    # `return ""` that made a git failure look like a detached HEAD.
    _d_norepo = _pmb / 'resolver-no-repo'
    _d_norepo.mkdir(parents=True, exist_ok=True)
    _prev_cwd = os.getcwd()
    os.chdir(_d_norepo)
    try:
        with contextlib.redirect_stderr(io.StringIO()):
            _real_norepo = discover_deferrals._resolve_current_branch()
    finally:
        os.chdir(_prev_cwd)
    _d_repo, _ = _pm_tree('resolver-repo', branch='resolver-probe')
    os.chdir(_d_repo)
    try:
        with contextlib.redirect_stderr(io.StringIO()):
            _real_repo = discover_deferrals._resolve_current_branch()
    finally:
        os.chdir(_prev_cwd)
    assert_eq("#1374: the real branch resolver returns the sentinel on a git failure and the name on success (a blanket return '' would read a failure as a detached HEAD)",
              (True, 'resolver-probe'),
              (_real_norepo is discover_deferrals.BRANCH_UNRESOLVABLE, _real_repo))

    # A branch whose every character the keep-filter drops leaves the branch candidate
    # unformable. The filing fence falls back to pr-<N>-only because it is best-effort;
    # this gate must not, because that candidate is the sole source on a first entry.
    _d, _rev = _pm_tree('branch-slug-empty')
    try:
        discover_deferrals._resolve_current_branch = lambda: '\u0424\u0418\u041a\u0421'
        _rc, _so, _se = _dm_run([_PM_FLAG, '94'], _d)
    finally:
        discover_deferrals._resolve_current_branch = _saved_branch
    assert_eq("#1374: a non-empty branch deriving an EMPTY slug reports unestablished, never absent",
              (2, True), (_rc, 'unestablished: reason=branch-slug-empty' in _so))

    # A candidate root that exists but cannot be stat'd. classify_root reaches its verdict
    # through os.path.exists/isdir, which suppress every OSError, so without the gate's own
    # pre-probe an ELOOP/EIO candidate would classify `absent` and route to "skip".
    _d, _rev = _pm_tree('candidate-unreadable')
    _loop = _rev / 'pr-100'
    try:
        os.symlink(str(_loop), str(_loop))
        _sym_ok = True
    except (OSError, NotImplementedError, AttributeError):
        _sym_ok = False
        print("  #1374 candidate-ELOOP fixture unavailable: this host cannot create the symlink loop")
    if _sym_ok:
        _rc, _so, _se = _dm_run([_PM_FLAG, '100'], _d)
        assert_eq("#1374: a candidate root that cannot be inspected reports unestablished, never absent",
                  (2, True), (_rc, 'unestablished: reason=unreadable-directory' in _so))

    # _probe_review_root's except-OSError arm (distinct from its not-a-directory arm):
    # a non-directory ANCESTOR makes the stat raise rather than answer.
    _d = _pmb / 'review-root-ancestor-not-a-dir'
    (_d / '.prflow').mkdir(parents=True, exist_ok=True)
    (_d / '.prflow' / 'tmp').write_text('x', encoding='utf-8')
    _rc, _so, _se = _dm_run([_PM_FLAG, '101'], _d)
    assert_eq("#1374: a review root whose ancestor is not a directory reports unestablished, never absent",
              (2, True), (_rc, 'unestablished: reason=unreadable-review-root' in _so))

    # ---- AC18b: the argument dispatch does not disturb the discovery contract. The
    # ---- same root-only invocations the filing fence makes — including its unquoted
    # ---- word-split $SEARCH_DIRS form — classify and exit exactly as before, and the
    # ---- presence mode is unreachable except through the flag.
    _d, _rev = _pm_tree('dispatch-regression')
    _ok = _rev / 'pr-88'
    _dm_ok = _dm_manifest(_ok, 'run-a', '{"deferrals": [{"file": "a.py"}]}')
    _gone = str(_rev / 'pr-does-not-exist')
    _notdir = _rev / 'not-a-dir'
    _notdir.write_text('x', encoding='utf-8')
    assert_eq("#1374 AC18b: discovery mode over root paths is unchanged (clean, partial, all-failed)",
              (0, 3, 4, 2),
              (_dm_run([_gone, str(_ok)])[0],
               _dm_run([str(_notdir), str(_ok)])[0],
               _dm_run([str(_notdir)])[0],
               _dm_run([])[0]))
    assert_eq("#1374 AC18b: discovery mode still prints the discovered manifests",
              [_dm_ok], _dm_run([_gone, str(_ok)])[1].split())
    # The flag is reachable only as the FIRST argument: in any other position it is an
    # ordinary root path, which is what keeps a root that happens to look like a flag
    # from silently switching modes mid-list.
    _rc, _so, _se = _dm_run([str(_ok), _PM_FLAG])
    assert_eq("#1374 AC18b: the presence flag in a non-leading position is treated as a root path",
              (True, False), (_rc in (0, 3, 4), _so.startswith('present:')))
    # The fence passes $SEARCH_DIRS UNQUOTED, so the shell — not this process — splits it.
    # The in-process assertions above hand main() an already-split list and therefore
    # cannot observe that shape; this one drives the real word-split through `sh -c`.
    _ws = _subprocess.run(
        ['sh', '-c',
         'SEARCH_DIRS="$1 $2"; exec python3 "$0" $SEARCH_DIRS',
         str(SCRIPTS / 'discover-deferral-manifests.py'), _gone, str(_ok)],
        capture_output=True, text=True)
    assert_eq("#1374 AC18b: the fence's UNQUOTED $SEARCH_DIRS word-split still classifies both roots and prints the manifest",
              (0, [_dm_ok]), (_ws.returncode, _ws.stdout.split()))


# ── issue #603: the per-finding ledger, post-revision resolution, and convergence basis ──
#
# Rows are numbered to the issue's Testing Strategy list. The pure evaluators are driven
# in-process; the mutations and queries are driven through the real CLI in a temp dir,
# because their whole contract is exit codes, printed tokens, and stderr breadcrumbs.

_IAS603 = str(SCRIPTS / 'issue-audit-state.py')

def _ias_fork_selected(env):
    """Decide whether the fork driver below is usable, given an environment mapping.

    Taken as a function of an explicit mapping rather than reading `os.environ` inline so
    the `DEVFLOW_IAS_NO_FORK=1` escape hatch is assertable without re-importing this file.
    """
    return hasattr(os, 'fork') and env.get('DEVFLOW_IAS_NO_FORK') != '1'


# `os.fork` does not exist on Windows, where every call falls back to the real spawn.
_IAS_FORK_OK = _ias_fork_selected(os.environ)


def _ias_reset_module_state():
    """Return the already-imported `issue_audit_state` to its cold-import state.

    The fork child inherits the PARENT's module globals rather than re-importing, so any
    process-scoped memo the parent warmed would answer for the child's own cwd and its own
    first-emission bookkeeping. `_repo_root` is the load-bearing one: it is memoized and
    cwd-derived, so a warm entry would resolve this repository instead of the child's temp
    sandbox. A monkeypatched stand-in carries no `cache_clear`, hence the guard.
    """
    rr = getattr(issue_audit_state, '_repo_root', None)
    clear = getattr(rr, 'cache_clear', None)
    if clear is not None:
        clear()
    emitted = getattr(issue_audit_state, '_STATE_BREADCRUMB_EMITTED', None)
    if isinstance(emitted, set):
        emitted.clear()


def _ias_spawn(argv, cwd, stdin=None):
    """Spawn `issue-audit-state.py` as a real subprocess.

    This is both the Windows/opt-out fallback for `_ias_run` and the fidelity REFERENCE the
    A/B row below grades the fork driver against, so the two must stay one call shape.
    """
    return _subprocess.run([sys.executable, _IAS603, *argv], cwd=cwd, input=stdin,
                           capture_output=True, text=True)


def _ias_run(argv, cwd, stdin=None):
    """Drive `issue-audit-state.py`'s CLI in a forked child, or spawn it for real.

    Returns the same `CompletedProcess` shape `_ias_spawn` returns, and preserves everything
    the rows grade: the real exit status, the real stdout/stderr bytes, the real working
    directory, and full process isolation (the child `os._exit`s, so no state it mutates can
    reach the parent). What it drops is the interpreter startup and module import a spawn
    pays per call, which no assertion examines.

    Known divergence from `_ias_spawn`, inert for every input these rows drive: the child's
    streams are fixed UTF-8 rather than the locale encoding, and `stdin=None` gives the child
    `/dev/null` (immediate EOF) where the spawn inherits this process's own stdin.
    """
    if not _IAS_FORK_OK:
        return _ias_spawn(argv, cwd, stdin=stdin)
    args = [_IAS603, *argv]
    # stdin arrives through a temp FILE, never a pipe: a pipe would deadlock the pair once
    # a payload exceeded the kernel buffer, since the parent cannot write and drain at once.
    stdin_file = None
    out_r = out_w = err_r = err_w = None
    pid = None
    try:
        if stdin is not None:
            stdin_file = tempfile.NamedTemporaryFile('w', encoding='utf-8', delete=False)
            stdin_file.write(stdin)
            stdin_file.close()
        out_r, out_w = os.pipe()
        err_r, err_w = os.pipe()
        # Flush before forking, or the child inherits the parent's buffered bytes and emits
        # a second copy of everything already written to this file's own stdout/stderr.
        sys.stdout.flush()
        sys.stderr.flush()
        pid = os.fork()
        if pid == 0:
            rc = 1
            try:
                # A failure anywhere in this setup must still say WHY on the child's stderr:
                # a bare `os._exit(1)` here is indistinguishable from a genuine CLI exit 1.
                try:
                    os.close(out_r)
                    os.close(err_r)
                    os.dup2(out_w, 1)
                    os.dup2(err_w, 2)
                    os.close(out_w)
                    os.close(err_w)
                    fd0 = os.open(
                        stdin_file.name if stdin_file is not None else os.devnull,
                        os.O_RDONLY)
                    os.dup2(fd0, 0)
                    os.close(fd0)
                    sys.stdin = os.fdopen(0, 'r', encoding='utf-8')
                    sys.stdout = os.fdopen(1, 'w', encoding='utf-8')
                    sys.stderr = os.fdopen(2, 'w', encoding='utf-8')
                    os.chdir(cwd)
                    sys.argv = [_IAS603, *[str(a) for a in argv]]
                    _ias_reset_module_state()
                except BaseException:
                    import traceback
                    try:
                        with os.fdopen(os.dup(2), 'w', encoding='utf-8') as _diag:
                            _diag.write('_ias_run: fork-child setup failed\n')
                            traceback.print_exc(file=_diag)
                    except BaseException:
                        pass
                    raise
                rc = 0
                try:
                    issue_audit_state.main()
                except SystemExit as exc:
                    rc = 0 if exc.code is None else (
                        exc.code if isinstance(exc.code, int) else 1)
                except BaseException:
                    import traceback
                    traceback.print_exc()
                    rc = 1
                sys.stdout.flush()
                sys.stderr.flush()
            finally:
                os._exit(rc if isinstance(rc, int) else 1)
        os.close(out_w)
        out_w = None
        os.close(err_w)
        err_w = None
        chunks = {}
        failures = {}
        owned = set()

        def _drain(key, fd):
            # A drain thread that dies without recording WHY would leave chunks[key]
            # absent, and an empty-string stdout would then be graded as real output.
            try:
                buf = []
                fh = os.fdopen(fd, 'rb')
                # Membership means "this thread closed, or will close, this pipe end";
                # clearing it before `os.fdopen` takes the fd would leak it, since the
                # parent then skips it too.
                owned.add(key)
                with fh:
                    while True:
                        b = fh.read(65536)
                        if not b:
                            break
                        buf.append(b)
                chunks[key] = b''.join(buf)
            except BaseException as exc:
                failures[key] = exc
                # Release this pipe end HERE when `os.fdopen` never took it: the parent
                # reaches `os.waitpid` before its own finally arm, so an undrained,
                # unclosed pipe wedges the pair forever once the child fills it.
                if key not in owned:
                    try:
                        os.close(fd)
                    except OSError:
                        pass
                    owned.add(key)

        # Both streams drain concurrently: a child that fills one pipe's buffer while the
        # parent is blocked reading the other would wedge the pair.
        threads = [_threading1040.Thread(target=_drain, args=(k, fd))
                   for k, fd in (('out', out_r), ('err', err_r))]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        # Clear only the ends `os.fdopen` actually took: clearing on a failure that
        # happened before that leaks the pipe end past this call's finally arm.
        if 'out' in owned:
            out_r = None
        if 'err' in owned:
            err_r = None
        _, status = os.waitpid(pid, 0)
        pid = None
        for key in ('out', 'err'):
            if key in failures:
                raise AssertionError(
                    f'_ias_run: the {key} drain thread failed for {args!r}') \
                    from failures[key]
        if os.WIFSIGNALED(status):
            rc = -os.WTERMSIG(status)
        else:
            rc = os.WEXITSTATUS(status)
        return _subprocess.CompletedProcess(
            args, rc,
            _ias_decode(chunks.get('out', b'')), _ias_decode(chunks.get('err', b'')))
    finally:
        for fd in (out_r, out_w, err_r, err_w):
            if fd is not None:
                try:
                    os.close(fd)
                except OSError:
                    pass
        if pid:
            try:
                os.waitpid(pid, 0)
            except OSError:
                pass
        if stdin_file is not None:
            try:
                os.unlink(stdin_file.name)
            except OSError:
                pass


def _ias_decode(raw):
    """Decode a captured stream the way `subprocess.run(text=True)` presents one.

    Universal-newline translation is applied here because the rows were authored against the
    spawn, which translates; a fork path that did not would diverge on any CR-carrying byte.
    """
    return raw.decode('utf-8', 'replace').replace('\r\n', '\n').replace('\r', '\n')


def _stage_bytes(run, path):
    """Record the staged write for a draft file's CURRENT bytes (issue #1104).

    A fresh file-arm `record-dispatch` refuses bytes that are not recoverable from the
    run's recorded byte history, so establishing that history is a PRECONDITION of a
    file-arm fixture — the same class of setup as the harness's own `init`, not an
    assertion. The artifact is content-addressed with the digest inside the `.staged.md`
    suffix, the property `record-staged-write` and the byte-history reader key on (not
    the `issue-draft-<slug>.<nonce>.<digest>.staged.md` shape `resolve_staged_path`
    produces). The recipe lives here rather than in each harness so no
    `record-dispatch`-driving harness drifts on the artifact name or the digest form.

    Every step is checked and a failure RAISES, the same discipline `_Run603._field`
    applies to its own setup calls: an unestablished precondition would otherwise surface
    as a crowd of unrelated fixtures refusing with `file-arm-requires-staged-write`,
    attributed to their own subjects and to no line naming staging.

    `run` is any harness exposing `.tmp`, `.slug` and the `(*argv, nonce=…)` call shape.
    Returns the artifact path, so a caller that must keep the next round's kind selection
    cold can retire it once the dispatch it enabled has run.
    """
    src = Path(path) if os.path.isabs(str(path)) else Path(run.tmp, path)
    if not src.exists():
        raise AssertionError(
            f'#1104 harness: _stage_bytes({run.slug}) found no draft at {src} — the '
            'byte-history precondition cannot be established for a file-arm dispatch')
    data = src.read_bytes()
    _h = _subprocess.run(['git', 'hash-object', '--stdin', '--no-filters'],
                         input=data, capture_output=True)
    dig = _h.stdout.decode().strip()
    if _h.returncode != 0 or not dig:
        raise AssertionError(
            f'#1104 harness: _stage_bytes({run.slug}) could not digest {src} '
            f'(rc={_h.returncode}); stderr={_h.stderr.decode()!r}')
    art = Path(run.tmp, f'staged-{run.slug}.{dig}.staged.md')
    art.write_bytes(data)
    _r = run('record-staged-write', run.slug, '--path', str(art), '--digest', dig,
             nonce=True)
    if _r.returncode != 0:
        raise AssertionError(
            f'#1104 harness: _stage_bytes({run.slug}) failed to record the staged write '
            f'(rc={_r.returncode}); stderr={_r.stderr!r}')
    return art


def _entry603(eid, summary, status='unresolved', **kw):
    e = {'id': eid, 'summary': summary, 'status': status,
         'ingested_status': kw.pop('ingested_status', 'unresolved')}
    e.update(kw)
    return e


def _round603(num, outcome='REVISE', adj='REVISE', unresolved=1, must_revise=1,
              ledger=None):
    r = _round(num, 'file', outcome, digest=f'D{num}', adj=adj, unresolved=unresolved,
               must_revise=must_revise, advisory=0, invalid=0)
    if ledger is not None:
        r['findings'] = ledger
    return r


class _Run603:
    """A scratch run driven through the real CLI in its own temp directory."""

    def __init__(self, tmp, slug='s603'):
        self.tmp = tmp
        self.slug = slug
        self.nonce = self._field(self('init', slug), 'nonce=', 'init')

    @staticmethod
    def _field(proc, token, what):
        """Parse a `token`-prefixed field out of a SETUP call's stdout, or name the failure.

        The setup calls (`init`, `record-dispatch`) are preconditions, not assertions: a
        harness that indexed straight into `stdout.split(token)` surfaced a broken
        precondition as an opaque `IndexError` from inside the fixture, attributed to no
        row. Check the returncode and the field's presence first so a setup failure names
        the command, its exit code, and its stderr.
        """
        if proc.returncode != 0 or token not in proc.stdout:
            raise AssertionError(
                f'#603 harness: {what} did not establish {token!r} '
                f'(rc={proc.returncode}); stdout={proc.stdout!r} stderr={proc.stderr!r}')
        return proc.stdout.split(token, 1)[1].split()[0].strip()

    def __call__(self, *argv, stdin=None, nonce=False, autostage=True):
        # issue #1104: a fresh file-arm dispatch now requires the dispatched bytes in the
        # byte history. Establishing it here keeps a fixture whose subject is NOT that
        # guarantee expressing only its own subject; the rows that DO grade the guarantee
        # pass `autostage=False` and drive the raw CLI. The arm is read as the VALUE
        # following `--arm`, never as a bare membership test over argv — a path or a
        # marker token spelled `file` would otherwise acquire the staging side effect.
        art = None
        if (autostage and argv and argv[0] == 'record-dispatch'
                and '--arm' in argv and '--draft-file' in argv
                and argv[argv.index('--arm') + 1] == 'file'):
            art = _stage_bytes(self, argv[argv.index('--draft-file') + 1])
        args = list(argv)
        if nonce:
            args += ['--nonce', self.nonce]
        out = _ias_run(args, self.tmp, stdin=stdin)
        if art is not None:
            # Retire the artifact once it has done its job. Retained, it would let the
            # NEXT round's kind selection reconstruct these bytes and answer `targeted`,
            # silently re-aiming a downstream fixture whose subject is the ledger, the
            # budgets, or convergence — none of which is the round kind. The rows that
            # grade a scoped round's reachability stage explicitly and keep theirs.
            #
            # DISCLOSED CONSEQUENCE: this leaves a `staged_paths` record naming a file
            # that no longer exists, and it pins the revise-then-open-round fixtures to a
            # state a real post-#1104 run does not reach — such a run keeps its artifact,
            # so the tool selects `targeted` and refuses a hardcoded `--kind discovery`
            # with `kind-mismatch`. That combined flow is covered on its own by the #793
            # kind-mismatch row; what this deletion buys is that a fixture whose subject
            # is something else does not have to be re-graded to keep expressing it.
            art.unlink(missing_ok=True)
        return out

    def open_round(self, n, verdict='REVISE', findings=1):
        Path(self.tmp, 'd.md').write_text(f'draft {n}\n', encoding='utf-8')
        # issue #1751: no round is free-funded any more, so every round this helper opens is
        # user-elected. Record the election before the dispatch (the funding gate refuses an
        # unfunded open). A test driving the unfunded/ceiling path dispatches directly rather
        # than through this helper.
        self('record-offer', self.slug, '--accepted', nonce=True)
        digest = self._field(
            self('record-dispatch', '--kind', 'discovery', self.slug, '--round', str(n), '--arm', 'file',
                 '--draft-file', 'd.md', nonce=True), 'digest=', 'record-dispatch')
        self('record-return', self.slug, '--round', str(n), '--verdict', verdict,
             '--findings-count', str(findings), '--carriage-object-id', digest,
             nonce=True)
        return digest

    def adjudicate(self, n, verdict='REVISE', must=1, unresolved='1', ledger=None):
        argv = ['record-adjudication', self.slug, '--round', str(n), '--verdict', verdict,
                '--must-revise', str(must), '--advisory', '0', '--invalid', '0',
                '--unresolved-must-revise', str(unresolved)]
        if ledger is not None:
            argv.append('--ledger-stdin')
        return self(*argv, stdin=ledger, nonce=True)


def _with_run603(fn):
    with tempfile.TemporaryDirectory() as tmp:
        fn(_Run603(tmp))


# ── the fork driver itself is a subject, not only an instrument ──
#
# Every row below this point reads its verdict through `_ias_run`, so a driver that lost
# stdout, mistranslated an exit status or silently stopped delivering stdin would recolour
# those verdicts rather than fail. These rows grade the driver directly, against the real
# spawn it replaced.

import signal as _signal1567


def _ias_driver_rows(r):
    r.open_round(1, 'REVISE', 2)
    # An ingestion REFUSAL is the A/B subject because it is non-mutating and reads stdin:
    # the same argv can be replayed through both drivers against one tree without the first
    # replay changing what the second sees.
    argv = ['record-adjudication', r.slug, '--round', '1', '--verdict', 'REVISE',
            '--must-revise', '2', '--advisory', '0', '--invalid', '0',
            '--unresolved-must-revise', '2', '--ledger-stdin', '--nonce', r.nonce]
    payload = 'unresolved: finding A\n'
    forked = _ias_run(argv, r.tmp, stdin=payload)
    spawned = _ias_spawn(argv, r.tmp, stdin=payload)
    assert_eq("#1567 fidelity: the fork driver and a real spawn agree on rc/stdout/stderr",
              (spawned.returncode, spawned.stdout, spawned.stderr),
              (forked.returncode, forked.stdout, forked.stderr))
    # Control on the A/B subject itself: a driver that delivered NO stdin at all would still
    # be refused, and the two drivers would still agree — on a verdict about nothing. A
    # second payload refused for a different reason proves the bytes reached the child.
    other = _ias_run(argv, r.tmp, stdin='unresolved: a\nfinding with no status prefix\n')
    assert_eq("#1567 fidelity: the A/B subject really is stdin-sensitive on both streams",
              (1, 1, True, True),
              (spawned.returncode, other.returncode,
               spawned.stderr != other.stderr, spawned.stderr.strip() != ''))
    # A query is the second A/B subject: it is the shape whose STDOUT the rows parse, and a
    # refusal alone would leave the stdout channel graded only as the empty string.
    qargv = ['query-convergence', r.slug, '--nonce', r.nonce]
    fq, sq = _ias_run(qargv, r.tmp), _ias_spawn(qargv, r.tmp)
    assert_eq("#1567 fidelity: a stdout-bearing query agrees across both drivers",
              (sq.returncode, sq.stdout, sq.stderr, True),
              (fq.returncode, fq.stdout, fq.stderr, sq.stdout.strip() != ''))
    # The opt-out must actually select the fallback; the two A/B rows above are what proves
    # the arm it selects is correct.
    assert_eq("#1567: DEVFLOW_IAS_NO_FORK=1 deselects the fork driver, and only that value",
              (False, hasattr(os, 'fork'), hasattr(os, 'fork')),
              (_ias_fork_selected({'DEVFLOW_IAS_NO_FORK': '1'}),
               _ias_fork_selected({'DEVFLOW_IAS_NO_FORK': '0'}),
               _ias_fork_selected({})))
    if _IAS_FORK_OK:
        # The signal arm: a child that dies on a signal has no exit status to report, and
        # WEXITSTATUS of such a status is 0 — which would read as a PASSING command.
        _real_main = issue_audit_state.main

        def _suicide():
            os.kill(os.getpid(), _signal1567.SIGTERM)

        issue_audit_state.main = _suicide
        try:
            killed = _ias_run(['query-convergence', r.slug], r.tmp)
        finally:
            issue_audit_state.main = _real_main
        assert_eq("#1567: a signal-killed child reports -SIGTERM, never a 0 exit status",
                  -_signal1567.SIGTERM, killed.returncode)


_with_run603(_ias_driver_rows)


# Row 1 — the regression row: the reported deadlock, and its release through resolution.
def _row1(r):
    r.open_round(1, 'REVISE', 3)
    r.adjudicate(1, 'REVISE', 3, '3',
                 'unresolved: finding A\nunresolved: finding B\nunresolved: finding C\n')
    r('record-revision', r.slug, '--after-round', '1', '--stdin-digest',
      stdin='revised bytes\n', nonce=True)
    assert_eq("#603-1 regression: T1 holds while the ledger carries unresolved entries",
              't1=hold t2=hold coverage=not-hold calibration=not-hold reason=steering-unestablished',
              decided(r('query-triggers', r.slug, nonce=True).stdout))
    assert_eq("#603-1 regression: convergence refuses while entries are unresolved",
              'converged=no reason=unresolved-must-revise-remain basis=none unledgered_revise=none',
              decided(r('query-convergence', r.slug, nonce=True).stdout))
    res = r('record-resolution', r.slug, '--round', '1', '--revision-ordinal', '1',
            '--resolved-ids', '1,2,3', nonce=True)
    assert_eq("#603-1/AC2 regression: record-resolution derives remaining=0",
              (0, 'round=1 revision_ordinal=1 frozen=3 remaining=0'),
              (res.returncode, decided(res.stdout)))
    assert_eq("#603-1/AC6 regression: T1 releases once every entry is settled",
              't1=not-hold t2=hold coverage=not-hold calibration=not-hold reason=steering-unestablished',
              decided(r('query-triggers', r.slug, nonce=True).stdout))
    assert_eq("#603-1/AC7 regression: the run converges on a resolution basis",
              'converged=yes reason= basis=resolution unledgered_revise=none',
              decided(r('query-convergence', r.slug, nonce=True).stdout))


_with_run603(_row1)


# Row 2 — ledger-ingestion refusals and the divergent-but-legal shape.
def _row2(r):
    r.open_round(1, 'REVISE', 3)
    bare = r.adjudicate(1, 'REVISE', 3, '3')
    assert_eq("#603-2/AC1: REVISE + settled count without --ledger-stdin is refused",
              (1, True), (bare.returncode, 'ledger-required' in bare.stderr))
    for name, k, u, payload, token in (
        ('line count different from K', 3, '3', 'unresolved: a\nunresolved: b\n',
         'ledger-line-count'),
        ('unresolved: line count different from <n>', 3, '3',
         'unresolved: a\nunresolved: b\nresolved: c\n', 'ledger-unresolved-count'),
        ('empty summary', 1, '1', 'unresolved: \n', 'ledger-empty-summary'),
        ('missing status prefix', 1, '1', 'finding with no prefix\n',
         'ledger-status-prefix'),
        ('protocol-vocabulary summary', 1, '1', 'unresolved: fix status=resolved parsing\n',
         'ledger-protocol-vocabulary'),
        ('widened-vocabulary summary', 1, '1',
         'unresolved: answers converged=yes on a stale basis\n',
         'ledger-protocol-vocabulary'),
        # An INTERIOR CR survives the \n split and str.strip(), and would otherwise reach
        # query-findings' trailing summary= field and clobber the reconciliation surface.
        ('a summary carrying an interior carriage return', 1, '1',
         'unresolved: first half\rsecond half\n', 'ledger-summary-control-char'),
        # issue #889: a non-positive quoted-draft-line coordinate. `@0` parses via
        # `@(\d+)` but is not a 1-based line number, so it is refused at ingestion.
        ('a non-positive draft-line coordinate', 1, '1', 'unresolved@0: a\n',
         'ledger-draft-line-range'),
        # issue #889: the accepted set is the UNPADDED decimal form. `@007` parses via
        # `@(\d+)`; normalizing it to 7 would silently accept a coordinate the author
        # did not write, so it is refused with its own distinct breadcrumb (distinct
        # from `ledger-draft-line-range` above, so a test asserting one cannot be
        # satisfied by the other firing).
        ('a zero-padded draft-line coordinate', 1, '1', 'unresolved@007: a\n',
         'ledger-draft-line-format'),
        ('a zero-padded zero draft-line coordinate', 1, '1', 'unresolved@00: a\n',
         'ledger-draft-line-format'),
    ):
        got = r.adjudicate(1, 'REVISE', k, u, payload)
        assert_eq(f"#603-2/AC1: {name} is refused with a named breadcrumb",
                  (1, True), (got.returncode, token in got.stderr))
    ok = r.adjudicate(1, 'REVISE', 3, '1',
                      'resolved: a\nresolved: b\nunresolved: c\n')
    assert_eq("#603-2/AC1: the divergent must-revise 3 / unresolved 1 shape ingests",
              0, ok.returncode)
    assert_eq("#603-2/AC5: it derives an effective count of 1",
              'converged=no reason=unresolved-must-revise-remain basis=none unledgered_revise=none',
              decided(r('query-convergence', r.slug, nonce=True).stdout))
    # Read the recorded state, not query-findings: that query prints only
    # round/id/status/summary, so an stdout check could not observe this stamp at all and
    # would pass unchanged if _ingest_ledger stopped writing it. The stamp is load-bearing —
    # _validate_ledger uses it to excuse a resolved entry from naming a revision ordinal, and
    # _settling_ordinal reads it as ordinal 0.
    _st = issue_audit_state.load_state(r.slug, root=r.tmp)
    assert_eq("#603-2/AC1: an ingested-resolved entry carries resolved-at-adjudication",
              ('resolved', 'resolved-at-adjudication'),
              (lambda e: (e['ingested_status'], e.get('ingest_provenance')))(
                  _st['rounds'][0]['findings'][0]))


_with_run603(_row2)


# Row 2d — the positive controls for row 2's control-character refusal, plus the
# reopen-of-an-ingested-`resolved` entry and the batch atomicity of the two id-list
# channels. The refusal rows above assert only that a bad payload is rejected; without
# these, a guard that rejected EVERY summary would leave them all green.
def _row2d(r):
    r.open_round(1, 'REVISE', 3)
    # A trailing CRLF is what a Windows-shell heredoc emits on every line. The guard reads
    # the STRIPPED summary, so this must ingest and record the bare text — the positive
    # control proving the refusal targets an interior splitter, not any CR at all.
    crlf = r.adjudicate(1, 'REVISE', 3, '2',
                        'resolved: first half second half\r\n'
                        'unresolved: finding B\r\nunresolved: finding C\r\n')
    assert_eq("#603-2d: a CRLF-terminated ledger ingests (the row-2 fixture is otherwise "
              "valid — only the interior CR is refused)", 0, crlf.returncode)
    found = r('query-findings', r.slug, nonce=True).stdout.strip().split('\n')
    assert_eq("#603-2d: the trailing CR is stripped, not recorded",
              'round=1 id=1 status=resolved summary=first half second half', found[0])
    # AC4's pre-revision arm over an entry that was never resolved by a revision: its
    # settling stamp is the ingestion provenance, and reopen must still take it.
    reop = r('record-reopen', r.slug, '--round', '1', '--ids', '1', nonce=True)
    assert_eq("#603-2d/AC4: an ingested-resolved entry reopens with no revision recorded",
              (0, 'round=1 reopened=1 remaining=3'), (reop.returncode, decided(reop.stdout)))
    # Batch atomicity: one bad id in the list must mutate NOTHING, so the whole batch is
    # re-issuable after correcting it. Named ids 2 (legal) and 9 (unknown).
    bad = r('record-invalidate', r.slug, '--round', '1', '--ids', '2,9',
            '--reason', 'misclassified: advisory', nonce=True)
    assert_eq("#603-2d/AC19: a batch naming one unknown id is refused",
              (1, True), (bad.returncode, 'unknown' in bad.stderr))
    assert_eq("#603-2d/AC19: and mutated no entry in the batch (remaining unchanged)",
              'round=1 id=2 status=unresolved summary=finding B',
              r('query-findings', r.slug, nonce=True).stdout.strip().split('\n')[1])
    bad_r = r('record-reopen', r.slug, '--round', '1', '--ids', '2,9', nonce=True)
    assert_eq("#603-2d/AC4: record-reopen is atomic over its id list too",
              (1, True), (bad_r.returncode, 'unknown' in bad_r.stderr))


_with_run603(_row2d)


# issue #889 — the `@<n>` ledger coordinate's PREFIX-ORDERING contract. The parser matches
# the plain status prefix before the `@<n>` form, so a summary that itself begins `@12: `
# must be stored verbatim and capture no coordinate. Without a driver the ordering claim
# in the parser's own comment is untested, and a reordered candidate list would silently
# eat the first token of such a summary.
def _row889_at_prefix(r):
    r.open_round(1, 'REVISE', 1)
    r.adjudicate(1, 'REVISE', 1, '1', 'unresolved: @12: a summary starting with @n\n')
    _f = issue_audit_state.load_state(r.slug, root=r.tmp)['rounds'][0]['findings'][0]
    assert_eq("#889: a summary beginning `@n: ` is stored verbatim, capturing no coordinate",
              ('@12: a summary starting with @n', False),
              (_f['summary'], 'quoted_draft_line' in _f))


_with_run603(_row889_at_prefix)


