_draft.write_text('# T\n\n## A\n\nrevised AGAIN after the scope was frozen\n',
                  encoding='utf-8')
_bm = _r('record-dispatch', '--kind', 'targeted', _r.slug, '--round', '2', '--arm', 'file',
         '--draft-file', 'd.md', '--scope-file', _scope, nonce=True)
